import { NextResponse } from 'next/server';

import { COMPONENT_TYPE, INTERACTION_CALLBACKS, LINK_BUTTON_STYLE } from './constants';
import DiscordEmbed from './utils/DiscordEmbed';
import DiscordMessage from './utils/DiscordMessage';

import type { NextRequest } from 'next/server';

import { SUPPORT_LINK } from '~/constants';
import { env } from '~/env.mjs';
import getBaseUrl from '~/utils/getBaseUrl';

const HELP_MESSAGE = new DiscordEmbed(`Hey there! 👋 Need some help with Hooks.gg? Here's a quick rundown:

Hooks.gg is a powerful messaging tool for Discord Community Builders. You can create and send custom messages using webhooks, but to access all the features, head over to our website at [hooks.gg](https://hooks.gg).

On the website, you'll find a fully-interactive and intuitive message editor that allows you to customize your messages with Embeds, Markdown, and more. You can also save your messages to the cloud, collaborate with others using shared saves, and even load messages for your server directly into the editor.

To get started, simply visit [hooks.gg](https://hooks.gg) and explore all the amazing features we offer. If you have any questions or need assistance, feel free to reach out to us in our support server.

Happy messaging!_ _ ✉️🚀`)
  .setThumbnail({ url: 'https://hooks.gg/static/images/logo.png' })
  .setColor(14895353);

const commands: Record<string, (request: NextRequest, interaction: RawCommand) => NextResponse | Promise<NextResponse>> = {
  help: () => {
    const message = new DiscordMessage({ ephemeral: true, embeds: [HELP_MESSAGE] })
      .addComponentRow([
        {
          type: COMPONENT_TYPE.BUTTON,
          label: 'Hooks.gg Website',
          style: LINK_BUTTON_STYLE,
          url: 'https://hooks.gg',
        },
        {
          type: COMPONENT_TYPE.BUTTON,
          label: 'Support Server',
          style: LINK_BUTTON_STYLE,
          url: SUPPORT_LINK,
        },
      ]);
    const payload = {
      type: INTERACTION_CALLBACKS.CHANNEL_MESSAGE_WITH_SOURCE,
      data: message.createPayload().data,
    };
    return NextResponse.json(payload, { status: 200 });
  },

  get_message: async (_, interaction) => {
    const response = await fetch(`${getBaseUrl()}/api/interactions-server`, {
      method: 'POST',
      headers: {
        Accept: 'application/json',
        'Content-Type': 'application/json',
        'x-hooks-api-token': env.HOOKS_API_TOKEN,
      },
      body: JSON.stringify(interaction),
    })
      .then(async (res) => ({ data: res.status === 200 ? await res.json() : '', status: res.status }))
      .catch((err) => {
        console.error(err);
        return { data: '', status: 500 };
      });
    return NextResponse.json(response.data, { status: response.status });
  },
};

export default commands;

import lang from '../../../../src/lang';
import { getLocalizedStrings } from '../common';

import help from './help';

import type { PartialPostSlashCommand, PostSlashCommand } from '../types';

type PartialCommands = Record<SlashCommand, PartialPostSlashCommand>;
const partialSlashCommands: PartialCommands = {
  help,
};

const slashCommands = (Object.entries(partialSlashCommands) as Entries<PartialCommands>).map(([command, meta]) => toCommandPayload(command, meta));

function toCommandPayload(command: SlashCommand, meta: PartialPostSlashCommand): PostSlashCommand<SlashCommand> {
  return {
    ...meta,
    name: lang['en-US'].appCommands.slash[command].name as SlashCommand,
    description: lang['en-US'].appCommands.slash[command].description,
    name_localizations: getLocalizedStrings('slash', command, 'name'),
    description_localizations: getLocalizedStrings('slash', command, 'description'),
  };
}

export default slashCommands;

import FormData from 'form-data';

import { COMPONENT_TYPE, FILE_FORM_JSON_KEY, MessageFlags } from '../constants';

import type {
  APIActionRowComponent, APIAttachment, APIComponentInMessageActionRow, APIMessageReference, InteractionResponseType,
} from 'discord-api-types/v10';
import type DiscordEmbed from './DiscordEmbed';

type ActionRowComponent = APIActionRowComponent<APIComponentInMessageActionRow>;
type Attachment = APIAttachment;
type MessageReference = APIMessageReference;

export interface DiscordFile {
  id: number;
  buffer: Buffer;
  filename: string;
  ext: string;
}

type DiscordAttachment = Pick<Attachment, 'id'> & Partial<Attachment>;

type RequestFormDataFunction = () => {
  data?: FormData;
  headers?: Record<string, unknown>;
};

type RichDiscordMessage = {
  embeds?: DiscordEmbed[];
} | {
  files?: DiscordFile[];
};

export type DiscordMessageOptions = RichDiscordMessage & {
  content?: undefined | string;
  components?: undefined | ActionRowComponent[];
  attachments?: never[];
  ephemeral?: undefined | boolean;
  preserve?: undefined | boolean;
};

function constructDiscordFileId(id: number) {
  return `files[${id}]`;
}

export default class DiscordMessage {
  #content?: undefined | string;

  #components?: undefined | ActionRowComponent[];

  #embeds?: DiscordEmbed[];

  #files?: DiscordFile[];

  #preserve = false;

  #ephemeral: undefined | boolean;

  #messageReference?: MessageReference;

  public constructor(message: DiscordMessageOptions | { lazy: true }) {
    if ('content' in message) {
      this.#content = message.content;
    }
    if ('components' in message) {
      this.#components = message.components;
    }
    if ('embeds' in message && message.embeds) {
      if (this.#files) throw Error('cannot specify both files and embed');
      const { embeds } = message;
      this.#embeds = Array.isArray(embeds) ? embeds : [embeds];
    }
    if ('files' in message && message.files) {
      const { files } = message;
      this.#files = Array.isArray(files) ? files : [files];
    }
    if ('ephemeral' in message && message.ephemeral) {
      this.#ephemeral = true;
    }
    if ('preserve' in message) {
      this.#preserve = !!message.preserve;
    }
  }

  public get ephemeral(): boolean {
    return !!this.#ephemeral;
  }

  public set ephemeral(ephemeral: boolean) {
    this.#ephemeral = ephemeral;
  }

  public get components() {
    return this.#components;
  }

  public set components(components: undefined | ActionRowComponent[]) {
    this.#components = components;
  }

  public get hasFiles() {
    return !!this.#files?.length;
  }

  public setContent(content: string) {
    this.#content = content;
    return this;
  }

  public addComponentRow(components: ActionRowComponent['components']) {
    this.#components = this.#components ?? [];
    this.#components.push({ type: COMPONENT_TYPE.ACTION_ROW, components });
    return this;
  }

  public addEmbed(embed: DiscordEmbed) {
    this.#embeds = this.#embeds ?? [];
    this.#embeds.push(embed);
    return this;
  }

  public addFile(file: DiscordFile) {
    this.#files = this.#files ?? [];
    this.#files.push(file);
    return this;
  }

  public softSetEphemeral(ephemeral: boolean) {
    if (this.#ephemeral === undefined) this.#ephemeral = ephemeral;
  }

  public setReference(messageId: string, channelId: string) {
    this.#messageReference = { message_id: messageId, channel_id: channelId };
    return this;
  }

  public createPayload(type?: InteractionResponseType):
  { data: DiscordMessageData | DiscordMessagePostData, createForm?: never }
  | { createForm: RequestFormDataFunction, data?: never } {
    if (this.#files) {
      const files = this.#files;

      const createForm = () => {
        const form = new FormData();

        const seen = new Set<number>();

        const attachments: DiscordAttachment[] = [];
        for (const {
          id, buffer, filename, ext,
        } of files) {
          if (seen.has(id)) throw Error(`duplicate file id \`${id}\``);
          seen.add(id);
          form.append(constructDiscordFileId(id), buffer, `${filename}.${ext}`);
          attachments.push({ id: `${id}`, ephemeral: true });
        }

        let payloadJson: PostAttachments | DiscordMessagePostData = { ...this.constructMessage(true), attachments };
        if (type) {
          const tmp = payloadJson;
          payloadJson = { type, data: tmp };
        }
        form.append(FILE_FORM_JSON_KEY, JSON.stringify(payloadJson));

        const headers = form.getHeaders();
        return { data: form, headers };
      };

      return { createForm };
    }

    if (type) {
      return { data: { type, data: this.constructMessage() } };
    }

    return { data: this.constructMessage() };
  }

  private constructMessage(forAttachment: true): Record<never, never> | DiscordMessageData;

  private constructMessage(forAttachment?: false): DiscordMessageData;

  private constructMessage(forAttachment = false): Record<never, never> | DiscordMessageData {
    let message: undefined | DiscordMessageData;

    if (this.#content) {
      message = { content: this.#content };
    }

    if (this.#components) {
      if (!message) message = { components: this.#components };
      else message.components = this.#components;
    }

    if (this.#embeds) {
      const embeds = this.#embeds.map((e) => e.createPayload());
      if (!message) message = { embeds };
      else message.embeds = embeds;
    }

    if (message) {
      return this.mergeOptions(message);
    }

    if (forAttachment) {
      return this.mergeOptions({});
    }

    throw Error('empty message');
  }

  public mergeOptions<T extends Partial<DiscordMessageData>>(message: T): T {
    let tmp = { ...message };
    if (this.#ephemeral) {
      tmp.flags = MessageFlags.EPHEMERAL;
    }
    if (this.#messageReference) {
      tmp.message_reference = this.#messageReference;
    }
    if (!this.#preserve) {
      tmp = {
        content: '', components: [], embeds: [], attachments: [], ...tmp,
      };
    }
    return tmp;
  }
}

import type { TRPCClientErrorBase } from '@trpc/client';
import type { DefaultErrorShape } from '@trpc/server';
import type {
  APIActionRowComponent,
  APIChatInputApplicationCommandInteractionData,
  APIUserApplicationCommandInteractionData,
  APIMessageApplicationCommandInteractionData,
  APIApplicationCommandInteractionDataOption,
  ApplicationCommandOptionType, APIAttachment, ChannelType,
  APIWebhook as DiscordWebhook,
  APIGuildChannel,
  APIGuildMember, APIInteractionGuildMember, InteractionResponseType, InteractionType, APIMessage, APIMessageComponent,
  APIMessageComponentInteractionData as MessageComponentDataBase, APIModalSubmission,
  APIGuild as ParacordGuild,
  APIComponentInMessageActionRow, APIInteractionDataResolved, APIRole, APIUser, Locale,
  APIMessageTopLevelComponent,
  APIButtonComponentWithURL,
  APIMessageComponentEmoji,
  APIContainerComponent,
  APISectionComponent,
  APITextDisplayComponent,
  APIThumbnailComponent,
  APIMediaGalleryComponent,
  APIMediaGalleryItem,
  APIFileComponent,
  APISeparatorComponent,
  APIComponentInContainer,
  APIUnfurledMediaItem,
  ButtonStyle,
  ComponentType,
  SeparatorSpacingSize,
} from 'discord-api-types/v10';
import type {
  ComponentProps, Dispatch, FunctionComponent, ReactNode as ReactNodeType, SetStateAction,
} from 'react';
import type { Embed, EmbedField } from '~/components/DiscordMessageEditor';
import type { EmojiType } from '~/components/EmojiPicker/Picker/components/EmojiPicker.types';

declare global {
  type ReactNode = ReactNodeType;
  // eslint-disable-next-line @typescript-eslint/ban-types
  type FC<P = {}> = FunctionComponent<P>;

  type StateSetter<T> = Dispatch<SetStateAction<T>>;
  type VoidReturn<Args extends unknown[]> = (...args: Args) => void;

  type KeysMatching<T, V> = { [K in keyof T]-?: T[K] extends V ? K : never }[keyof T];
  type NotUndefined<T> = T extends undefined ? never : T;
  type Entries<T> = NotUndefined<{ [K in keyof T]: [K, NotUndefined<T[K]>] }[keyof T]>[];
  type KeysNotWithType<T, P> = {
    [K in keyof T]: T[K] extends P ? never : K;
  }[keyof T];

  type DiscordId = string;
  type DatabaseId = string;

  type UserGuild = Pick<Required<ParacordGuild>, 'id' | 'name' | 'icon' | 'owner' | 'permissions'>;

  interface Webhook extends Pick<DiscordWebhook, 'id' | 'avatar'> {
    token: string;
    name: string;
    guild_id: string;
    channel_id: string;
    channel?: null | undefined | DiscordChannel;
  }
  type Guild = Pick<ParacordGuild, 'id' | 'name' | 'icon' | 'emojis'>;

  type UserPreference = {
    recentGuild?: string;
    recentMessageIds?: string[];
  };

  type ApiScheduledMessage = {
    id: string;
    cron: string | null;
    error: string | null;
    sendAt: number;
    sent: boolean;
  };

  type PartialApiMessage = {
    id: string;
    guildId?: string;
    name: string;
    createdAt: number;
    updatedAt: number;
    previewImageNonce: null | string;
  };

  type ApiMessage = {
    id: string;
    guildId?: string;
    name: string;
    data: MessageData;
    updatedAt: number;
    createdAt: number;
    previewImageNonce: null | string;
    recentWebhookId: null | string;
    recentThreadId: null | string;
    recentMessageId: null | string;
    scheduledMessage?: ApiScheduledMessage;
  };

  type ActiveMessage = Partial<Omit<ApiMessage, 'data' | 'updatedAt' | 'name'>> & Pick<ApiMessage, 'updatedAt' | 'name'> & {
    data: EditableMessageData;
  };

  type StoredMessage = {
    messageId: string;
    guildId: string;
    data: MessageData;
    webhookId?: string;
    threadId?: string;
    droppedComponentTypes?: readonly string[];
  };

  type MessageData = Pick<Partial<APIMessage>, 'content'> & {
    username?: string;
    avatar_url?: string;
    embeds?: Embed[];
    components?: SupportedTopLevelComponent[];
    flags?: number;
    allowed_mentions?: {
      parse?: ('user' | 'here' | 'everyone')[];
      users?: DiscordId[];
      roles?: DiscordId[];
      replied_user?: boolean;
    };
    thread_name?: string;
  };

  type DiscordThread = {
    id: string;
    name: string;
  };

  type DiscordChannel = {
    id: string;
    name: string;
    type: ChannelType;
    threads: null | DiscordThread[];
  };

  type UrlQueryOptions = {
    server?: string;
  };

  type Theme = 'dark' | 'light';

  type ClientPreferences = {
    message_servers_order: 'asc' | 'desc';
    message_servers_view: 'grid' | 'list';
    message_f_order: 'asc' | 'desc';
    message_f_view: 'grid' | 'list';
    message_f_sort: 'name' | 'updatedAt' | 'createdAt';
  };

  interface LocalStorage {
    theme: Theme;
    frequentlyUsedEmojis: EmojiType[];
    message: ActiveMessage;
    messageDrafts: MessageDrafts;
    client_preferences: ClientPreferences;
  }

  type MessageDraft = { data: EditableMessageData, name: string, editedAt: number };
  type MessageDrafts = Record<string, MessageDraft>;

  interface LocalStore<K extends keyof LocalStorage> {
    current: LocalStorage[K];
    set: (value: LocalStorage[K]) => void;
    clear: VoidFunction;
  }

  type AsyncEffectCallback = () => Promise<unknown> | unknown;

  type SvgComponentProps = ComponentProps<'svg'> & { title?: string, titleId?: string };
  type SvgComponent = FC<SvgComponentProps>;
  type ClassNameProps = { className?: undefined | string };

  type Dimensions = { width: number, height: number };

  type DiscordMessageStyle = 'cozy' | 'compact';

  type EditableMessageData = Omit<MessageData, 'embeds' | 'components'> & {
    embeds?: EditableEmbed[];
    components?: EditableTopLevelComponent[];
  };

  type EditableEmbed = Omit<Embed, 'fields'> & {
    _key: string;
    fields?: EditableField[];
  };

  type EditableField = EmbedField & { _key: string };

  // COMPONENTS V2 — Editable types with _key for stable React keys

  type EditableLinkButton = {
    _key: string;
    type: ComponentType.Button;
    style: ButtonStyle.Link;
    label?: string;
    emoji?: APIMessageComponentEmoji;
    url: string;
    disabled?: boolean;
  };

  type EditableActionRow = {
    _key: string;
    type: ComponentType.ActionRow;
    components: EditableLinkButton[];
  };

  type EditableTextDisplay = {
    _key: string;
    type: ComponentType.TextDisplay;
    content: string;
  };

  type EditableThumbnail = {
    _key: string;
    type: ComponentType.Thumbnail;
    media: { url: string };
    description?: string;
    spoiler?: boolean;
  };

  type EditableSection = {
    _key: string;
    type: ComponentType.Section;
    components: EditableTextDisplay[];
    accessory: EditableThumbnail | EditableLinkButton;
  };

  type EditableMediaGalleryItem = {
    _key: string;
    media: { url: string };
    description?: string;
    spoiler?: boolean;
  };

  type EditableMediaGallery = {
    _key: string;
    type: ComponentType.MediaGallery;
    items: EditableMediaGalleryItem[];
  };

  type EditableFile = {
    _key: string;
    type: ComponentType.File;
    file: { url: string };
    spoiler?: boolean;
  };

  type EditableSeparator = {
    _key: string;
    type: ComponentType.Separator;
    divider: boolean;
    spacing: SeparatorSpacingSize;
  };

  type EditableContainerChild =
    | EditableActionRow
    | EditableTextDisplay
    | EditableSection
    | EditableMediaGallery
    | EditableFile
    | EditableSeparator;

  type EditableContainer = {
    _key: string;
    type: ComponentType.Container;
    components: EditableContainerChild[];
    accent_color?: number;
    spoiler?: boolean;
  };

  type EditableTopLevelComponent =
    | EditableActionRow
    | EditableTextDisplay
    | EditableSection
    | EditableMediaGallery
    | EditableFile
    | EditableSeparator
    | EditableContainer;

  type TRPCQueryError = TRPCClientErrorBase<DefaultErrorShape>;

  // DISCORD MESSAGE — Supported (non-editable) component types
  // These mirror the Zod schema and restrict to link-button-only action rows

  type SupportedLinkButton = {
    type: ComponentType.Button;
    style: ButtonStyle.Link;
    label?: string;
    emoji?: APIMessageComponentEmoji;
    url: string;
    disabled?: boolean;
  };

  type SupportedActionRow = {
    type: ComponentType.ActionRow;
    components: SupportedLinkButton[];
  };

  type SupportedTextDisplay = {
    type: ComponentType.TextDisplay;
    content: string;
  };

  type SupportedThumbnail = {
    type: ComponentType.Thumbnail;
    media: { url: string };
    description?: string;
    spoiler?: boolean;
  };

  type SupportedSection = {
    type: ComponentType.Section;
    components: SupportedTextDisplay[];
    accessory: SupportedThumbnail | SupportedLinkButton;
  };

  type SupportedMediaGalleryItem = {
    media: { url: string };
    description?: string;
    spoiler?: boolean;
  };

  type SupportedMediaGallery = {
    type: ComponentType.MediaGallery;
    items: SupportedMediaGalleryItem[];
  };

  type SupportedFile = {
    type: ComponentType.File;
    file: { url: string };
    spoiler?: boolean;
  };

  type SupportedSeparator = {
    type: ComponentType.Separator;
    divider: boolean;
    spacing: SeparatorSpacingSize;
  };

  type SupportedContainerChild =
    | SupportedActionRow
    | SupportedTextDisplay
    | SupportedSection
    | SupportedMediaGallery
    | SupportedFile
    | SupportedSeparator;

  type SupportedContainer = {
    type: ComponentType.Container;
    components: SupportedContainerChild[];
    accent_color?: number;
    spoiler?: boolean;
  };

  type SupportedTopLevelComponent =
    | SupportedActionRow
    | SupportedTextDisplay
    | SupportedSection
    | SupportedMediaGallery
    | SupportedFile
    | SupportedSeparator
    | SupportedContainer;

  type DiscordAttachment = Pick<APIAttachment, 'id'> & Partial<APIAttachment>;

  type MessageCommon = Partial<Pick<APIMessage, 'flags' | 'message_reference'>>;
  type PostContent = MessageCommon & {
    content: string;
    embeds?: Embed[];
    components?: APIMessageTopLevelComponent[];
    attachments?: DiscordAttachment[];
  };
  type PostEmbeds = MessageCommon & {
    content?: string;
    embeds: Embed[];
    components?: APIMessageTopLevelComponent[];
    attachments?: DiscordAttachment[];
  };
  type PostComponents = MessageCommon & {
    content?: string;
    embeds?: Embed[];
    components: APIMessageTopLevelComponent[];
    attachments?: DiscordAttachment[];
  };

  type DiscordMessageData = PostContent | PostEmbeds | PostComponents;

  type PostAttachments = MessageCommon
  & Partial<DiscordMessageData>
  & { attachments: DiscordAttachment[] };

  type DiscordMessagePostData = DiscordMessageData
  | PostAttachments
  | { type: InteractionResponseType, data: DiscordMessageData | PostAttachments };

  type ButtonStyleName = 'PRIMARY' | 'SECONDARY' | 'SUCCESS' | 'DANGER';

  // INTERACTIONS

  type InteractionCallbackName = 'PONG' | 'CHANNEL_MESSAGE_WITH_SOURCE'
  | 'DEFERRED_CHANNEL_MESSAGE_WITH_SOURCE' | 'DEFERRED_UPDATE_MESSAGE'
  | 'UPDATE_MESSAGE' | 'APPLICATION_COMMAND_AUTOCOMPLETE_RESULT' | 'MODAL';

  type InteractionTypeName = 'PING' | 'APPLICATION_COMMAND' | 'MESSAGE_COMPONENT' | 'APPLICATION_COMMAND_AUTOCOMPLETE' | 'MODAL_SUBMIT';

  type CommandName = 'help';
  type UserCommand = never;
  type MessageCommand = 'get_message';

  type SlashCommand = CommandName;

  type DiscordGuildMember = APIGuildMember & Pick<Required<APIGuildMember>, 'user'>;

  interface RawInteraction<Type extends InteractionType = InteractionType> {
    id: string;
    application_id: string;
    type: Type;
    guild_id?: string;
    channel_id: string;
    member?: APIInteractionGuildMember;
    user?: APIUser;
    token: string;
    version: 1;
    message?: APIMessage;
    app_permissions?: string;
    locale?: Locale;
    guild_locale?: Locale;
    _acknowledged?: boolean;
  }

  interface InteractionTypes extends Record<string, InteractionType> {
    PING: InteractionType.Ping;
    APPLICATION_COMMAND: InteractionType.ApplicationCommand;
    MESSAGE_COMPONENT: InteractionType.MessageComponent;
    APPLICATION_COMMAND_AUTOCOMPLETE: InteractionType.ApplicationCommandAutocomplete;
    MODAL_SUBMIT: InteractionType.ModalSubmit;
  }

  type RequiredMessage = APIMessage & { components: APIMessageComponent[] };

  // COMMAND
  type ApplicationCommandTypeName = 'CHAT_INPUT' | 'USER' | 'MESSAGE';

  interface RawCommand extends RawInteraction<InteractionTypes['APPLICATION_COMMAND']> {
    data: SlashCommandData | UserCommandData | MessageCommandData;
  }

  interface SlashCommandData extends Pick<APIChatInputApplicationCommandInteractionData, 'type' | 'name' | 'resolved' | 'options'> {
    name: CommandName;
    resolved?: AugmentedResolvedData;
    options?: ApplicationCommandOptions;
  }

  type ApplicationCommandOptions = [SubCommandOption] | CommandUserInputOption[];

  interface SubCommandOption extends Pick<Required<APIApplicationCommandInteractionDataOption>, 'name' | 'type'> {
    type: Extract<ApplicationCommandOptionType, 1 | 2>;
    options: ApplicationCommandOptions;
  }

  interface CommandUserInputOption extends Pick<Required<APIApplicationCommandInteractionDataOption>, 'name' | 'type' | 'value' | 'focused'> {
    type: Exclude<ApplicationCommandOptionType, 1 | 2>;
  }

  interface UserCommandData extends Pick<APIUserApplicationCommandInteractionData, 'type' | 'name' | 'target_id' | 'resolved'> {
    resolved: AugmentedResolvedData & Pick<Required<AugmentedResolvedData>, 'users'>;
  }

  interface MessageCommandData extends Pick<APIMessageApplicationCommandInteractionData, 'type' | 'name' | 'target_id' | 'resolved'> {
    resolved: AugmentedResolvedData & Pick<Required<AugmentedResolvedData>, 'messages'>;
  }

  // COMPONENT
  interface RawMessageComponent extends RawInteraction<InteractionTypes['MESSAGE_COMPONENT']> {
    data: MessageComponentData;
    message: RequiredMessage;
  }

  type MessageComponentData = ButtonData | SelectMenuData;

  interface ButtonData extends MessageComponentDataBase {
    component_type: 2;
  }
  interface SelectMenuData extends MessageComponentDataBase {
    component_type: 3;
    values: string[];
  }

  // MODAL
  interface RawModalSubmit extends RawInteraction<InteractionTypes['MODAL_SUBMIT']> {
    data: APIModalSubmission;
    message: RequiredMessage;
  }

  // RESOLVED DATA

  type ResolvedMember = Pick<APIGuildMember, 'avatar' | 'communication_disabled_until' | 'joined_at' | 'nick' | 'pending' | 'permissions' | 'premium_since' | 'roles'>;
  type ResolveDataMembers = Record<string, ResolvedMember>;

  type ResolvedUser = Pick<APIUser, 'avatar' | 'discriminator' | 'id' | 'public_flags' | 'username' | 'bot'>;
  type ResolveDataUsers = Record<string, ResolvedUser>;

  // `permissions`: computed permissions for the invoking user in the channel, including overwrites
  type ResolvedChannel = Pick<APIGuildChannel<ChannelType>, 'id' |'name' | 'parent_id' | 'type'> & { permissions: 'string' };
  type ResolveDataChannels = Record<string, ResolvedChannel>;

  type ResolvedMessage = Pick<APIMessage, 'id' | 'channel_id' | 'embeds' | 'content' | 'author'>;
  type ResolveDataMessages = Record<string, ResolvedMessage>;

  type ResolvedRole = APIRole;
