import type { EmojiNode, StrictSingleASTNode } from 'simple-markdown';
import type { BaseEditor, BaseRange } from 'slate';
import type { HistoryEditor } from 'slate-history';
import type { ReactEditor } from 'slate-react';

declare module 'slate' {
  interface CustomElement {
    type: 'div' | 'codeBlock' | 'blockQuote';
    children: Array<ElementType | CustomText>;
    lang: string;
    startCodeBlock: boolean;
    empty: boolean;
    ast?: EmojiNode;
  }

  export interface EmojiElement extends CustomElement {
    type: 'emoji' | 'nameEmoji' | 'discordEmoji';
    // text: string;
    ast: EmojiNode;
  }

  type ElementType = CustomElement | EmojiElement;

  type CustomText = { type: 'span', text: string, classNames?: string[], syntax?: boolean, ast?: Required<StrictSingleASTNode> };
  type CustomRange = BaseRange & { ast?: StrictSingleASTNode, classNames: string[], syntax?: boolean };

  interface CustomTypes {
    Editor: BaseEditor & ReactEditor & HistoryEditor;
    Element: ElementType;
    Text: CustomText;
    Range: CustomRange;
  }
}

'use client';

import { useSession } from 'next-auth/react';
import { redirect, RedirectType, usePathname, useSearchParams } from 'next/navigation';

const Redirects = () => {
  const { status } = useSession();
  const pathname = usePathname();
  const searchParams = useSearchParams();

  if (status === 'unauthenticated' && pathname !== '/message/m/0/edit' && pathname !== '/message/m/0/send') {
    redirect('/message/m/0/edit', RedirectType.replace);
  }

  const redirectGuildId = searchParams?.get('guild_id');
  if (redirectGuildId && (pathname === '/message')) {
    redirect(`/message/f/${redirectGuildId}`, RedirectType.replace);
  }

  return null;
};

export default Redirects;

