vi.mock('~/providers/ConfirmationProvider', async () => (await import('~/providers/MessageProvider/__tests__/helpers/messageProviderDeps')).CONFIRMATION_PROVIDER_MOCK);

import JsonModalBody from '../JsonModalBody';

afterEach(unmountDom);

function mount(setAllowMenuClose: (allow: boolean) => void = () => {}) {
  return mountInMessageProvider(
    <JsonModalBody onClose={() => {}} setAllowMenuClose={setAllowMenuClose} />,
  );
}

async function type(el: HTMLElement, json: string) {
  const view = EditorView.findFromDOM(el.querySelector('.cm-editor') as HTMLElement)!;
  await act(async () => {
    view.dispatch({ changes: { from: 0, to: view.state.doc.length, insert: json } });
  });
}

const CONFLICT_JSON = JSON.stringify({
  content: 'hello', flags: 32768, components: [{ type: 10, content: 'x' }],
});

describe('JsonModalBody — conflict resting state', () => {
  it('a conflicting edit rests on the dismissed-choice notice with a Resolve link, not the choice buttons', async () => {
    const el = mount();
    await type(el, CONFLICT_JSON);

    expect(el.textContent).toContain('nothing was loaded');
    expect(el.textContent).not.toContain('Save as Classic');
    expect(el.textContent).not.toContain('Save as Components V2');
    findButton(el, 'Resolve');
  });

  it('the resting conflict state leaves the menu closeable', async () => {
    const setAllowMenuClose = vi.fn();
    const el = mount(setAllowMenuClose);
    await type(el, CONFLICT_JSON);

    expect(setAllowMenuClose).toHaveBeenCalledWith(true);
    expect(setAllowMenuClose).not.toHaveBeenCalledWith(false);
  });

  it('the Resolve link reopens the choice buttons (pendingChoice stays reachable)', async () => {
    const el = mount();
    await type(el, CONFLICT_JSON);

    press(findButton(el, 'Resolve'));

    expect(el.textContent).toContain('Save as Classic');
    expect(el.textContent).toContain('Save as Components V2');
    expect(el.textContent).not.toContain('nothing was loaded');
  });

  it('V2 components beside an empty embed land as V2 with no choice', async () => {
    const el = mount();
    await type(el, JSON.stringify({
      flags: 32768, embeds: [{}], components: [{ type: 17, components: [{ type: 10, content: 'x' }] }],
    }));

    expect(el.textContent).not.toContain('nothing was loaded');
    expect(el.textContent).not.toContain('cannot contain embeds or content');
    expect(Array.from(el.querySelectorAll('button')).some((b) => b.textContent?.includes('Resolve'))).toBe(false);
  });
});

