import {
  cloneElement, Fragment, isValidElement, memo, useMemo,
} from 'react';
import { mergeRefs } from 'react-merge-refs';

import { usePopoverState } from './utils';

import type {
  ElementType, FC, HTMLProps, Ref,
} from 'react';

import Button, { type Props as ButtonProps } from '~/components/Button';

interface Props extends Omit<HTMLProps<HTMLElement>, 'as' | 'label' | 'ref'>,
Pick<ButtonProps, 'isDisabled' | 'tooltip'> {
  forwardedRef?: Ref<HTMLElement> | ((instance: HTMLElement | null) => void);
  as?: ElementType;
}

function replaceOnclickWithOnPress(props: Record<string, unknown>, toggleOpen: () => void) {
  if (props.onClick) {
    delete props.onClick;
    delete props.onKeyDown;
    delete props.onKeyUp;
  }
  props.onPress = toggleOpen;
}

const AnchoredPopoverTrigger: FC<Props> = ((allProps) => {
  const {
    children, as: childAs, forwardedRef, isDisabled, tooltip, ...props
  } = allProps;

  const state = usePopoverState();

  // In React 19, ref is a regular prop accessible via props.ref
  const childrenRef = isValidElement(children)
    ? (children.props as Record<string, unknown>).ref as Ref<HTMLElement> | undefined
    : undefined;
  const ref = useMemo(
    () => mergeRefs([state.refs.setReference, forwardedRef, childrenRef]),
    [state.refs.setReference, forwardedRef, childrenRef],
  );

  const stateProps: Record<string, string> = {};
  if (state.dataState && state.open) stateProps[`data-${state.dataState}-state`] = 'true';

  const floatingProps: Record<string, unknown> = {
    ref,
    ...state.getReferenceProps(props),
    ...stateProps,
    'data-headlessui-state': state.open ? 'open' : 'closed',
  };

  if (childAs === Fragment) {
    if (!isValidElement(children)) throw Error('<AnchorPopover.Trigger as={Fragment} /> must have a single child.');

    if (children.type === Button) {
      if (isDisabled !== undefined) floatingProps.isDisabled = isDisabled;
      if (tooltip !== undefined) floatingProps.tooltip = tooltip;
      replaceOnclickWithOnPress(floatingProps, state.toggleOpen);
    } else if ((isDisabled !== undefined || tooltip !== undefined) && children.type !== Button) {
      throw Error('<AnchorPopover.Trigger as={Fragment} /> can only have isDisabled or tooltip prop if child is a <Button />.');
    }
    return cloneElement(children, { ...(children.props as Record<string, unknown>), ...floatingProps });
  }

  const TriggerWrapper = childAs ?? Button;
  if (TriggerWrapper === Button) {
    if (isDisabled !== undefined) floatingProps.isDisabled = isDisabled;
    if (tooltip !== undefined) floatingProps.tooltip = tooltip;
    replaceOnclickWithOnPress(floatingProps, state.toggleOpen);
  } else if ((isDisabled !== undefined || tooltip !== undefined) && TriggerWrapper !== Button) {
    throw Error('<AnchorPopover.Trigger /> can only have isDisabled or tooltip prop if as={undefined || Button}.');
  }

  return (
    <TriggerWrapper {...floatingProps}>{children}</TriggerWrapper>
  );
});
AnchoredPopoverTrigger.displayName = 'AnchoredPopoverTrigger';

export default memo(AnchoredPopoverTrigger);

import { endOfMonth, getWeeksInMonth } from '@internationalized/date';
import { useCalendarGrid, useLocale } from 'react-aria';

import CalendarCell from './CalendarCell';

import type { CalendarState } from 'react-stately';

interface Props {
  state: CalendarState;
  offset?: { months?: number, weeks?: number, days?: number };
}

const CalendarGrid: FC<Props> = ({ state, offset = {} }) => {
  const { locale } = useLocale();
  const startDate = state.visibleRange.start.add(offset);
  const endDate = endOfMonth(startDate);
  const { gridProps, headerProps, weekDays } = useCalendarGrid({ startDate, endDate }, state);

  // Get the number of weeks in the month so we can render the proper number of rows.
  const weeksInMonth = getWeeksInMonth(startDate, locale);

  return (
    <table {...gridProps} cellPadding="0" className="flex-1">
      <thead {...headerProps} className="text-mute">
        <tr>
          {weekDays.map((day, index) => (
            <th key={index}><div className='flex justify-center'>{day}</div></th>
          ))}
        </tr>
      </thead>
      <tbody>
        {[...new Array(weeksInMonth).keys()].map((weekIndex) => (
          <tr key={weekIndex}>
            {state
              .getDatesInWeek(weekIndex, startDate)
              .map((date, i) => (date ? (
                <CalendarCell
                  key={i}
                  state={state}
                  date={date}
                  currentMonth={startDate}
                />
              ) : (
                <td key={i} />
              )))}
          </tr>
        ))}
      </tbody>
    </table>
  );
};

export default CalendarGrid;

