import {
  createCalendar, getLocalTimeZone, now, parseAbsoluteToLocal,
  Calendar as CalendarDate,
} from '@internationalized/date';
import classNames from 'classnames';
import { memo } from 'react';
import { useCalendar, useLocale } from 'react-aria';
import { useCalendarState } from 'react-stately';

import DateTimeField from '../DateTimeField';

import CalendarGrid from './CalendarGrid';
import CalendarHeader from './CalendarHeader';

import type { DateValue } from '@internationalized/date';
import type { CalendarStateOptions } from 'react-stately';

import Button from '~/components/Button';
import styles from '~/styles';

// ref: https://codesandbox.io/s/loving-julien-mf8usc

interface Props extends Omit<CalendarStateOptions, 'createCalendar' | 'locale' | 'value' | 'onChange'> {
  withOffset?: boolean;
  value: Date;
  onChange: (date: null | Date) => void;
}

const Calendar: FC<Props> = ({
  withOffset, value, onChange, ...props
}) => {
  const { locale } = useLocale();

  const stateValue = parseAbsoluteToLocal(value.toISOString());
  const stateOnChange = (date: DateValue | null) => { if (date) onChange(new Date(date.toDate(getLocalTimeZone()))); };

  const state = useCalendarState({
    locale,
    createCalendar: createCalendar as (name: string) => CalendarDate,
    value: stateValue,
    onChange: stateOnChange,
    ...props,
  });

  const { calendarProps, prevButtonProps, nextButtonProps } = useCalendar(props, state);

  return (
    <div className={classNames(calendarProps.className, styles.flex({ col: true, gap: 2 }), 'rounded bg-tertiary p-4 text-base transition-colors')}>
      <CalendarHeader
        state={state}
        calendarProps={calendarProps}
        prevButtonProps={prevButtonProps}
        nextButtonProps={nextButtonProps}
        withOffset={withOffset}
      />
      <div className="flex gap-8">
        <CalendarGrid state={state} />
        {!withOffset ? null : <CalendarGrid state={state} offset={{ months: 1 }} /> }
      </div>
      <DateTimeField
        placeholderValue={now(getLocalTimeZone())}
        value={stateValue}
        onChange={stateOnChange}
        aria-label="time"
      />
      <div className={classNames(styles.flex({ btw: true }))}>
        <Button className={styles.button.text} onPress={() => onChange(null)}>Clear</Button>
        <Button className={styles.button.text} onPress={() => onChange(new Date())}>Now</Button>
      </div>
    </div>
  );
};

export default memo(Calendar);

