interface Props {
  file: EditableFile;
  showEdit: boolean;
  setFile: (f: EditableFile) => void;
}

const FileEditor: FC<Props> = ({ file, showEdit, setFile }) => {
  const latest = useLatest(file);
  const [focused, setFocused] = useState(false);
  const { focusWithinProps } = useFocusWithin({ onFocusWithinChange: setFocused });

  const setUrl = useCallback(
    (val: string) => setFile({ ...latest.current, file: { url: val } }),
    [setFile],
  );

  const setSpoiler = useCallback(
    (val: boolean) => setFile({ ...latest.current, spoiler: val || undefined }),
    [setFile],
  );

  const fileName = useMemo(() => {
    try {
      const { url } = file.file;
      if (!url) return '';
      const segments = new URL(url).pathname.split('/');
      return segments[segments.length - 1] || url;
    } catch {
      return file.file.url || '';
    }
  }, [file.file.url]);

  return (
    <div
      {...(showEdit ? focusWithinProps : {})}
      className={classNames(
        'discord-visualizer__file',
        file.spoiler && 'discord-visualizer__file--spoiler',
      )}
