    >
      {file.spoiler && (
        <div className="discord-visualizer__file__spoiler-overlay">
          SPOILER
        </div>
      )}
      <DocumentIcon className="discord-visualizer__file__icon" />
      <span
        className={classNames(
          'discord-visualizer__file__name',
          !fileName && 'discord-visualizer__file__name--placeholder',
        )}
      >
        {fileName || 'attachment://filename.ext'}
      </span>

      <NullableComponent show={showEdit && focused}>
        <div className="absolute inset-x-0 top-full z-10 mt-1 rounded-md border border-tertiary bg-secondary p-3 shadow-lg">
          <div className="space-y-1.5">
            <label className="text-xs font-medium text-header-secondary">
              File URL
              <input
                type="url"
                value={file.file.url}
                placeholder="attachment://filename.png"
                className="mt-0.5 block w-full rounded-md border border-tertiary bg-primary px-2 py-1 text-sm text-header-primary placeholder:text-text-mute"
                onChange={(e) => setUrl(e.target.value)}
              />
            </label>
            <label
              className="flex items-center gap-1.5 text-xs font-medium text-header-secondary"
            >
              <input
                type="checkbox"
                checked={!!file.spoiler}
                onChange={(e) => setSpoiler(e.target.checked)}
                className="rounded border-tertiary"
              />
              Spoiler
            </label>
          </div>
        </div>
      </NullableComponent>
    </div>
  );
};

