import {
  memo, useCallback, useMemo, useState,
} from 'react';

import { defaultEmojiCategories, getCategoryIdentifier } from '../../utils';

import CategoryItem from './CategoryItem';
import CustomCategoryItem from './CustomCategoryItem';
import useSidebarState from './useSidebarState';

import type { MutableRefObject, Ref, UIEventHandler } from 'react';
import type { CustomCategory, DefaultEmojiCategory, EmojiCategory } from '../EmojiPicker.types';

import Button from '~/components/Button';
import { useFrequentEmojis } from '~/utils/hooks';
import { useIsMobile } from '~/providers/IsMobileProvider';

const TOP_OFFSET = 8;
const MARGIN = 8;
const MOBILE_PADDING = 16;
const DEFAULT_MARGIN_BOTTOM = 2;
const CATEGORY_SIZE = 32;
const FULL_ITEM_HEIGHT = CATEGORY_SIZE + MARGIN;
const MOBILE_ITEM_WIDTH = CATEGORY_SIZE + MARGIN * 2;
const DIVIDER_HEIGHT = 24;

function calculateInsetStyle(startIdx: number, itemSize: number, isMobile: boolean) {
  if (isMobile) return { inset: `0 0 0 ${startIdx * itemSize}px` };
  return { inset: `${TOP_OFFSET + (startIdx * itemSize)}px 0.5rem 0 0.5rem` };
}

function calculateHeightStyle(allCategories: EmojiCategory[], itemSize: number, isMobile: boolean) {
  const itemLength = allCategories.length * itemSize;
  if (isMobile) return { width: `${itemLength - (MOBILE_PADDING * 2) - (MARGIN * 2)}px` };
  return { height: `${itemLength - DIVIDER_HEIGHT - MARGIN + (DEFAULT_MARGIN_BOTTOM * defaultEmojiCategories.length)}px` };
}

interface Props {
  customCategories: CustomCategory[];
  sidebarItems: MutableRefObject<Record<string, number>>;
  scrollToCategory: (category: string, forceSidebar?: boolean) => void;
  activeCategory: string;
}

function CategoryList({ ref: propRef, ...props }: Props & { ref?: Ref<HTMLDivElement | null> }) {
  const {
    scrollToCategory, sidebarItems, customCategories, activeCategory,
  } = props;
  const { current: frequentEmojis } = useFrequentEmojis();

  const [startIdx, setStartIdx] = useState(0);
  const isMobile = useIsMobile();

  const itemSize = isMobile ? MOBILE_ITEM_WIDTH : FULL_ITEM_HEIGHT;

  const allCategories = useMemo<EmojiCategory[]>(() => {
    const tmp = [
    { name: 'frequentlyUsed', emojis: frequentEmojis } as DefaultEmojiCategory,
    ...customCategories,
    ...defaultEmojiCategories,
    ];
    sidebarItems.current = tmp.reduce<Record<string, number>>((acc, category, idx) => {
      acc[getCategoryIdentifier(category)] = idx * itemSize;
      return acc;
    }, {});
    return tmp;
  }, [frequentEmojis, customCategories]);

  const {
    visibleCustomCategories, visibleDefaultCategories, showFrequentlyUsed, withDivider,
  } = useSidebarState(allCategories, customCategories, startIdx, isMobile);

  const insetStyle = useMemo(() => calculateInsetStyle(startIdx, itemSize, isMobile), [startIdx]);
  const heightStyle = useMemo(() => calculateHeightStyle(allCategories, itemSize, isMobile), [allCategories.length]);
  const jumpToBottom = useCallback(() => scrollToCategory(defaultEmojiCategories[0].name, true), []);

  return (
    <div className='absolute w-12 mobile:relative mobile:h-12 mobile:w-full mobile:grid-row-[3/4] mobile:grid-col-[2/3] desktop:left-0 desktop:bottom-0 desktop:top-16 desktop:rounded-bl-lg'>
      <div
        ref={propRef}
        className='no-scroll absolute inset-0 h-full min-h-0 bg-tertiary mobile:overflow-x-scroll desktop:overflow-y-scroll'
        onScroll={useCallback<UIEventHandler<HTMLDivElement>>((e) => {
          const { scrollTop, scrollLeft } = e.currentTarget;
          const scroll = isMobile ? scrollLeft : scrollTop;
          const start = Math.floor(scroll / itemSize);
          setStartIdx(start);
        }, [itemSize])}
      >
        <ul
          style={insetStyle}
          className='absolute contain-layout mobile:flex mobile:items-center'
        >
          {showFrequentlyUsed ? (
            <CategoryItem
              category='frequentlyUsed'
              scrollToCategory={scrollToCategory}
              active={activeCategory === 'frequentlyUsed'}
            />
          ) : null}
          {!visibleCustomCategories.length ? null : (
            <>
              {visibleCustomCategories.map((category) => (
                <CustomCategoryItem
                  key={category.id}
                  category={category}
                  scrollToCategory={scrollToCategory}
                  active={activeCategory === category.id}
                />
              ))}
              {withDivider ? <hr className='my-3 border-b border-solid border-modifier-accent' /> : null}
            </>
          )}
          {visibleDefaultCategories.map((category) => (
            <CategoryItem
              key={category.name}
              category={category.name}
              scrollToCategory={scrollToCategory}
              active={activeCategory === category.name}
            />
          ))}
        </ul>
        <div style={heightStyle} className="invisible" />
      </div>
      {visibleDefaultCategories.length > 1 ? null : (
        <Button
          className="absolute flex h-12 w-full cursor-pointer items-center justify-center bg-tertiary text-interactive hover:text-interactive-hover mobile:top-0 mobile:right-2 mobile:h-full mobile:w-12 desktop:bottom-0 desktop:left-0"
          aria-label="Scroll to Unicode emoji"
          onPress={jumpToBottom}
          excludeFromTabOrder
        >
          <svg aria-hidden="true" role="img" width={isMobile ? '32' : '24'} height={isMobile ? '32' : '24'} viewBox="0 0 24 24">
            <path fill="currentColor" d="M12 2C6.477 2 2 6.477 2 12C2 17.522 6.477 22 12 22C17.523 22 22 17.522 22 12C22 6.477 17.523 2 12 2ZM8 6C9.104 6 10 6.896 10 8C10 9.105 9.104 10 8 10C6.896 10 6 9.105 6 8C6 6.896 6.896 6 8 6ZM18 14C18 16.617 15.14 19 12 19C8.86 19 6 16.617 6 14V13H18V14ZM16 10C14.896 10 14 9.105 14 8C14 6.896 14.896 6 16 6C17.104 6 18 6.896 18 8C18 9.105 17.104 10 16 10Z" />
          </svg>
        </Button>
      )}
    </div>
  );
}

export default memo(CategoryList);

import { useMemo } from 'react';

import isCustom from '../../utils/isCustom';

import type { CustomCategory, DefaultEmojiCategory, EmojiCategory } from '../EmojiPicker.types';

const LIST_LENGTH = 11;
const MOBILE_LIST_LENGTH = 11;

export default (
  allCategories: EmojiCategory[],
  customCategories: CustomCategory[],
  startIdx: number,
  isMobile: boolean,
) => useMemo(() => {
  const visibleCategories = allCategories.slice(startIdx, startIdx + (isMobile ? MOBILE_LIST_LENGTH : LIST_LENGTH));

  const visibleCustomCategories: CustomCategory[] = [];
  const visibleDefaultCategories: DefaultEmojiCategory[] = [];
  let showFrequentlyUsed = false;

  for (let i = 0; i < visibleCategories.length; i++) {
    const category = visibleCategories[i];
    if (category.name === 'frequentlyUsed') {
      showFrequentlyUsed = true;
      continue;
    }
    if (isCustom(category)) {
      visibleCustomCategories.push(category);
    } else if (category.name !== 'search') {
      visibleDefaultCategories.push(category);
    }
  }
  const withDivider = !isMobile && !!(visibleDefaultCategories.length || visibleCustomCategories.at(-1) === customCategories.at(-1));
  return {
    visibleCustomCategories, visibleDefaultCategories, showFrequentlyUsed, withDivider,
  };
}, [allCategories, customCategories, startIdx, isMobile]);

import Image from 'next/image';

import { defaultCategoryIcons, defaultCategoryNames } from '../../utils';
import isCustom from '../../utils/isCustom';
import { LeftArrowIcon } from '../Icons';

import type { EmojiCategory } from '../EmojiPicker.types';

import Button from '~/components/Button';
import { DEFAULT_IMAGE_URL } from '~/constants';
import { constructGuildIcon } from '~/utils';

interface Props {
  category: EmojiCategory;
  collapsed: boolean;
  toggleCollapsed: VoidFunction;
}

const SectionHeader: FC<Props> = ({
  category,
  collapsed,
  toggleCollapsed,
}) => (!isCustom(category) && category.name === 'search' ? null : (
  <div
    role="rowheader"
    className='sticky top-[-1px] z-10 flex h-8 items-center bg-secondary px-1 after:absolute after:left-0 after:top-[-2px] after:h-[3px] after:w-full after:bg-inherit'
  >
    <Button
      className="flex items-center justify-start text-[0.75rem] font-semibold text-header-secondary transition-colors duration-[125ms]"
      onPress={toggleCollapsed}
    >
      <div aria-hidden="true" className="mr-2 contents h-full">
        {isCustom(category) ? (
          <div>
            <Image
              className='!display-inherit flex h-4 w-4 items-center justify-center rounded bg-primary text-default'
              alt={category.name}
              src={category.guildAvatar ? constructGuildIcon({ id: category.id, icon: category.guildAvatar }, 40) : DEFAULT_IMAGE_URL}
              width='16'
              height='16'
              placeholder="empty"
              unoptimized
            />
          </div>
        ) : (() => {
          const Icon = defaultCategoryIcons[category.name];
          return <Icon width='16' height='16' />;
        })()}
      </div>

      <span className="mx-2 overflow-hidden whitespace-nowrap uppercase">
        {isCustom(category) ? category.name : defaultCategoryNames[category.name]}
      </span>
      <LeftArrowIcon
        width='16'
        height='16'
        style={{
          transition: 'transform .1s',
          transform: collapsed ? 'rotate(-90deg)' : 'rotate(0deg)',
        }}
      />
    </Button>
  </div>
));

export default SectionHeader;

