'use client';

import { Switch } from '@headlessui/react';
import anime from 'animejs';
import classNames from 'classnames';
import {
  memo, useEffect, useMemo, useRef, useState,
} from 'react';
import { useToggleButton } from 'react-aria';
import { useToggleState } from 'react-stately';

import type { PressEvent } from '@react-types/shared';
import type { AnimeInstance } from 'animejs';
import type { FC, Ref, RefObject } from 'react';
import type { AriaToggleButtonProps } from 'react-aria';

import styles from '~/styles';
import { createSyntheticClickEvent, withTouchEndFix } from '~/utils';

const TRANSITION_SPEED = 200;
const DURATION_STYLE = 'duration-200';

type PressedHandler = { setIsPressed: (isPressed: boolean) => void };

function setDirection(anim: AnimeInstance, seekTime: number) {
  const { direction, currentTime, duration } = anim;
  if (
    (currentTime < seekTime && direction === 'reverse')
    || (currentTime > seekTime && direction !== 'reverse')
  ) {
    anim.reverse();
    anim.completed = false;
  }

  const fromLeft = currentTime < seekTime;
  const shouldPause = ({ currentTime: ct }: AnimeInstance) => (fromLeft ? ct >= seekTime : ct <= seekTime);
  if (seekTime === 0 || seekTime === duration) {
    anim.change = undefined;
  } else {
    anim.change = (a) => {
      if (shouldPause(a) && !a.paused) {
        a.pause();
        a.seek(seekTime);
        a.change = undefined;
      }
    };
  }
}

interface Props extends Omit<AriaToggleButtonProps, 'onClick'> {
  className?: string;
  label?: string;
  description?: string;
  onClick?: (e: MouseEvent) => void;
}

function SwitchInner({ ref, ...props }: Props & PressedHandler & { ref?: Ref<HTMLButtonElement> }) {
  const { onClick, setIsPressed, ..._props } = props;

  const fixedProps = {
    ..._props,
    onPress: (e: PressEvent) => {
      _props.onPress?.(e);
      onClick?.(createSyntheticClickEvent(e));
    },
  };

  const state = useToggleState(props);
  const { isSelected } = state;

  const { buttonProps, isPressed } = useToggleButton(fixedProps, state, ref as RefObject<HTMLButtonElement>);

  const segment1Ref = useRef<SVGPolygonElement>(null);
  const segment2Ref = useRef<SVGPolygonElement>(null);

  const segment1Values = useMemo(() => {
    const val = [
      { value: '10 5, 45 40, 40 45, 5 10, 10 5', duration: 0 },
      { value: '7.5 21.5, 42.5 21.5, 42.5 28.5, 7.5 28.5, 7.5 21.5', duration: TRANSITION_SPEED / 2 },
      { value: '10 25, 25 40, 20 45, 5 30, 10 25', duration: TRANSITION_SPEED / 2 },
    ];
    return val;
  }, []);

  const segment2Values = useMemo(() => {
    const val = [
      { value: '5 40, 40 5, 45 10, 10 45, 5 40', duration: 0 },
      { value: '7.5 21.5, 42.5 21.5, 42.5 28.5, 7.5 28.5, 7.5 21.5', duration: TRANSITION_SPEED / 2 },
      { value: '15 40, 40 10, 45 15, 20 45, 15 40', duration: TRANSITION_SPEED / 2 },
    ];
    return val;
  }, []);

  const seg1 = useMemo(() => anime({
    targets: segment1Ref.current,
    points: segment1Values,
    easing: 'linear',
    duration: TRANSITION_SPEED,
    autoplay: false,
    direction: 'normal',
    loop: false,
  }), [segment1Ref.current]);
  const seg2 = useMemo(() => anime({
    targets: segment2Ref.current,
    points: segment2Values,
    easing: 'linear',
    duration: TRANSITION_SPEED,
    autoplay: false,
    direction: 'normal',
    loop: false,
  }), [segment2Ref.current]);

  useEffect(() => {
    if (isSelected) {
      seg1.play();
      seg2.play();
      seg1.seek(seg1.duration);
      seg2.seek(seg2.duration);
    }
  }, [segment1Ref.current]);

  useEffect(() => {
    setIsPressed(isPressed);

    const handleSegment = (segment: AnimeInstance) => {
      segment.pause();

      let seekTime: number;
      if (!isPressed && !isSelected) {
        seekTime = 0;
      } else if (isPressed && !isSelected) {
        seekTime = segment.duration / 2;
      } else if (!isPressed && isSelected) {
        seekTime = segment.duration;
      } else {
        // isPressed && isSelected
        seekTime = segment.duration / 2;
      }

      setDirection(segment, seekTime);
      if (segment.paused) segment.play();
    };

    handleSegment(seg1);
    handleSegment(seg2);
  }, [isPressed, isSelected]);

  return (
    <button type="button" className={props.className} {...withTouchEndFix(buttonProps)} ref={ref}>
      <span className={classNames('inline-block h-6 w-6 translate-x-1 rounded-full bg-white fill-text-mute stroke-text-mute transition-all ui-checked:translate-x-7 ui-checked:fill-fuchsia-800 ui-checked:stroke-fuchsia-800', DURATION_STYLE, styles.flex({ cx: true }), isPressed && 'w-9 ui-checked:!translate-x-4')}>
        <svg viewBox="-12.5 -12.5 75 75" className='h-6 w-6'>
          <polygon ref={segment1Ref} />
          <polygon ref={segment2Ref} />
        </svg>
      </span>
    </button>
  );
}

const SwitchComp = (props: Props) => {
  const {
    className, isSelected, label, description,
  } = props;

  const [isPressed, setIsPressed] = useState(false);

  return (
    <div className={styles.flex({ col: true, gap: 2 })}>
      <Switch.Group as="div" className={styles.flex({ btw: true, cy: true })}>
        {label && <Switch.Label className="font-semibold">{label}</Switch.Label>}
        <Switch
          className={classNames('toggle relative inline-flex h-8 w-14 items-center rounded-full bg-pos-0 transition-all ui-checked:bg-pos-100', isPressed && 'bg-pos-from-left ui-checked:bg-pos-from-right', DURATION_STYLE, className)}
          as={SwitchInner}
          checked={isSelected}
          setIsPressed={setIsPressed}
          {...props}
        />
      </Switch.Group>
      {description && <p className='text-sm'>{description}</p>}
    </div>
  );
};

export default memo(SwitchComp);

import {
  arrow, autoUpdate, flip, shift,
  useDismiss, useFloating, useFocus, useHover,
  useInteractions, useRole,
} from '@floating-ui/react';
import { Transition } from '@headlessui/react';
import classNames from 'classnames';
import React, {
  Fragment, isValidElement, memo, useRef,
} from 'react';
import { createPortal } from 'react-dom';

import type { Placement } from '@floating-ui/core';
import type { FC, PropsWithChildren, ReactNode } from 'react';

import Arrow from '~/components/Arrow';
import styles from '~/styles';
import { useTheme, useToggleState } from '~/utils/hooks';

const renderPortal = (node: React.JSX.Element, portal: boolean) => (portal ? createPortal(node, document.body) : node);

const ARROW_SIZE = 40;

export type Props = PropsWithChildren<{
  asFragment?: boolean;
  label: ReactNode;
  placement?: Placement;
  enterDelay?: number;
  leaveDelay?: number;
  afterLeave?: () => void;
  open?: boolean;
  portal?: boolean;
}>;

let currentClose: null | (() => void) = null;

const Tooltip: FC<Props> = (props) => {
  const {
    children,
    label,
    enterDelay = 0,
    leaveDelay = 150,
    afterLeave,
    open: propOpen,
    placement: propPlacement = 'top',
    asFragment = false,
    portal = false,
  } = props;

  const [isOpen, { setTrue: open, setFalse: close }] = useToggleState(propOpen);

  const arrowRef = useRef<HTMLDivElement>(null);

  const wrappedIsOpen = (bool: boolean) => {
    if (bool) {
      if (currentClose && currentClose !== close) {
        currentClose();
      }
      currentClose = close;
      open();
    } else {
      if (currentClose && currentClose === close) {
        currentClose = null;
      }
      close();
    }
  };

  const {
    x, y, refs: { setReference: reference, setFloating: floating }, strategy, context, middlewareData, placement,
  } = useFloating({
    open: propOpen ?? isOpen,
    onOpenChange: wrappedIsOpen,
    placement: propPlacement,
    middleware: [flip(), shift(), arrow({ element: arrowRef })],
    whileElementsMounted: autoUpdate,
  });

  const hover = useHover(context, {
    move: false, delay: { open: enterDelay, close: leaveDelay }, mouseOnly: true,
  });
  const focus = useFocus(context, { visibleOnly: true });
  const dismiss = useDismiss(context);
  const role = useRole(context, { role: 'tooltip' });

  const xOffset = (ARROW_SIZE * 0.33) / 2;
  // const yOffset = (ARROW_SIZE * 0.25) / 2;

  const yOffset = 0;

  const p = placement.split('-')[0];
  const staticSide = {
    top: { x: 0, y: -yOffset - 7 },
    right: { x: xOffset + 7, y: 0 },
    bottom: { x: 0, y: yOffset + 7 },
    left: { x: -xOffset - 7, y: 0 },
  }[p] ?? { x: 0, y: 0 };

  // Merge all the interactions into prop getters
  const { getReferenceProps, getFloatingProps } = useInteractions([
    hover,
    focus,
    dismiss,
    role,
  ]);

  const { current: theme } = useTheme();

  const referenceProps = getReferenceProps();

  let referenceEl;
  if (asFragment) {
    if (!isValidElement(children)) throw Error('<Tooltip asFragment /> must have a single child.');
    referenceEl = <children.type ref={reference} {...referenceProps} {...(children.props as Record<string, unknown>)} />;
  } else {
    referenceEl = (
      <div ref={reference} {...referenceProps} className='inline-block'>
        {children}
      </div>
    );
  }

  let offset;
  if (placement === 'top') offset = '-translate-y-1';
  if (placement === 'bottom') offset = 'translate-y-1';

  const tooltip = !isOpen ? null : renderPortal(
    <Transition
      as={Fragment}
      show={propOpen ?? isOpen}
      appear={portal}
      afterLeave={afterLeave}
      {...styles.transition({
        transition: 'will-change-[opacity] transition-opacity duration-300',
        closed: 'opacity-0',
        opened: 'opacity-100',
      })}
    >
      <div
        ref={floating}
        style={{
          position: strategy,
          top: `${staticSide.y + (y ?? 0)}px`,
          left: `${staticSide.x + (x ?? 0)}px`,
        }}
        {...getFloatingProps()}
        className={classNames(
          'z-50 max-w-[256px] select-none rounded bg-secondary p-1 px-2 text-sm shadow drop-shadow dark:bg-black',
          offset,
        )}
      >
        <Arrow
          arrow={middlewareData.arrow}
          arrowRef={arrowRef}
          placement={placement}
          fill={theme === 'dark' ? 'black' : 'var(--background-secondary)'}
          size={ARROW_SIZE}
          className='shadow drop-shadow'
        />
        <span className='font-medium'>{label}</span>
      </div>
    </Transition>,
    portal,
  );

  return (
    <>
      {referenceEl}
      {tooltip}
    </>
  );
};

export default memo(Tooltip);

