import { describe, it, expect, vi } from 'vitest';

// Mock env.mjs to prevent environment variable validation at import time
vi.mock('~/env.mjs', () => ({
  env: {
    NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test',
  },
}));

// Mock SVG components
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import { discordMessageShape, discordMessageImportShape, messageShape } from '~/server/api/utils/shapes';
import {
  makeLinkButton, makeActionRow, makeTextDisplay, makeThumbnail, makeSection,
  makeMediaGallery, makeFile, makeSeparator, makeContainer,
} from '~/utils/__tests__/helpers/components';

// ============================================================
// Tests: discordMessageShape (strict)
// ============================================================

describe('discordMessageShape (strict)', () => {
  it('accepts a valid message with content only', () => {
    const result = discordMessageShape.safeParse({
      content: 'Hello world',
    });
    expect(result.success).toBe(true);
  });

  it('accepts a valid message with embeds', () => {
    const result = discordMessageShape.safeParse({
      embeds: [{
        title: 'Test',
        description: 'A test embed',
      }],
    });
    expect(result.success).toBe(true);
  });

  it('accepts a message with V2 components', () => {
    const result = discordMessageShape.safeParse({
      components: [
        makeTextDisplay(),
        makeSection(),
        makeMediaGallery(),
        makeFile(),
        makeSeparator(),
        makeContainer([makeTextDisplay(), makeSeparator()]),
      ],
    });
    expect(result.success).toBe(true);
  });

  it('accepts a message with action row + link buttons', () => {
    const result = discordMessageShape.safeParse({
      components: [
        makeActionRow([makeLinkButton(), makeLinkButton()]),
      ],
    });
    expect(result.success).toBe(true);
  });

  it('accepts a message with flags field', () => {
    const result = discordMessageShape.safeParse({
      content: 'hello',
      flags: 32768,
    });
    expect(result.success).toBe(true);
  });

  it('rejects action row with more than 5 buttons', () => {
    const buttons = Array.from({ length: 6 }, () => makeLinkButton());
    const result = discordMessageShape.safeParse({
      components: [makeActionRow(buttons)],
    });
    expect(result.success).toBe(false);
  });

  it('accepts action row with zero buttons', () => {
    const result = discordMessageShape.safeParse({
      components: [makeActionRow([])],
    });
    expect(result.success).toBe(true);
  });

  it('rejects section with more than 3 text components', () => {
    const result = discordMessageShape.safeParse({
      components: [{
        type: 9,
