    });
    expect(result.success).toBe(false);
  });

  it('rejects link button without URL', () => {
    const result = discordMessageShape.safeParse({
      components: [
        makeActionRow([{ type: 2, style: 5, label: 'No URL' }]),
      ],
    });
    expect(result.success).toBe(false);
  });

  it('rejects link button with non-URL string', () => {
    const result = discordMessageShape.safeParse({
      components: [
        makeActionRow([{ type: 2, style: 5, url: 'not-a-url', label: 'Bad' }]),
      ],
    });
    expect(result.success).toBe(false);
  });

  it('rejects text display with content exceeding 4000 chars', () => {
    const result = discordMessageShape.safeParse({
      components: [makeTextDisplay('x'.repeat(4001))],
    });
    expect(result.success).toBe(false);
  });

  it('accepts text display with exactly 4000 chars', () => {
    const result = discordMessageShape.safeParse({
      components: [makeTextDisplay('x'.repeat(4000))],
    });
    expect(result.success).toBe(true);
  });

  it('rejects unsupported button styles (not link button)', () => {
    const result = discordMessageShape.safeParse({
      components: [
        makeActionRow([{ type: 2, style: 1, label: 'Primary', custom_id: 'test' }]),
