  });
});

// ============================================================
// Tests: discordMessageImportShape (lenient)
// ============================================================

describe('discordMessageImportShape (lenient import)', () => {
  it('accepts a valid message identically to strict shape', () => {
    const msg = {
      content: 'Hello',
      components: [makeTextDisplay(), makeSeparator()],
    };
    expect(discordMessageImportShape.safeParse(msg).success).toBe(true);
  });

  it('filters out unsupported component types (e.g., select menus) silently', () => {
    const msg = {
      content: 'Hello',
      components: [
        makeTextDisplay(),
        // Type 3 = select menu (not supported)
        { type: 3, custom_id: 'select', options: [{ label: 'A', value: 'a' }] },
        makeSeparator(),
      ],
    };
    const result = discordMessageImportShape.safeParse(msg);
    expect(result.success).toBe(true);
    if (result.success) {
      // Should have filtered out the select menu
      expect(result.data.components).toHaveLength(2);
      expect(result.data.components![0]).toMatchObject({ type: 10 });
      expect(result.data.components![1]).toMatchObject({ type: 14 });
    }
  });

  it('filters unsupported children from containers', () => {
    const msg = {
      components: [
        makeContainer([
          makeTextDisplay(),
          // Type 3 = unsupported child
          { type: 3, custom_id: 'sel', options: [] },
          makeSeparator(),
        ]),
      ],
    };
    const result = discordMessageImportShape.safeParse(msg);
    expect(result.success).toBe(true);
    if (result.success) {
      const container = result.data.components![0] as { components: unknown[] };
      expect(container.components).toHaveLength(2);
    }
  });

  it('removes container entirely if all children are unsupported', () => {
    const msg = {
      content: 'text',
      components: [
        makeContainer([
          { type: 3, custom_id: 'sel', options: [] },
          { type: 4, custom_id: 'input', style: 1, label: 'Input' },
        ]),
        makeTextDisplay(),
      ],
    };
    const result = discordMessageImportShape.safeParse(msg);
    expect(result.success).toBe(true);
    if (result.success) {
      // Container filtered out, only TextDisplay remains
      expect(result.data.components).toHaveLength(1);
      expect(result.data.components![0]).toMatchObject({ type: 10 });
    }
  });

  it('accepts message with no components at all', () => {
    const result = discordMessageImportShape.safeParse({ content: 'Hello' });
    expect(result.success).toBe(true);
  });

  it('handles non-array components gracefully', () => {
    // filterSupportedComponents returns non-arrays as-is, Zod optional handles undefined
    const result = discordMessageImportShape.safeParse({ content: 'Hello', components: undefined });
    expect(result.success).toBe(true);
  });

  it('filters components with completely unknown type numbers', () => {
    const msg = {
      components: [
        makeTextDisplay(),
        { type: 999, data: 'unknown' },
      ],
    };
    const result = discordMessageImportShape.safeParse(msg);
    expect(result.success).toBe(true);
    if (result.success) {
      expect(result.data.components).toHaveLength(1);
    }
  });

  it('a top-level thumbnail is filtered out by the lenient filter, not passed through to fail Zod', () => {
    const msg = {
      components: [makeThumbnail()],
    };
    const result = discordMessageImportShape.safeParse(msg);
    expect(result.success).toBe(true);
    if (result.success) expect(result.data.components).toEqual([]);
  });
});

// ============================================================
// Tests: discordMessageShape satisfies z.ZodType<MessageData>
// ============================================================

describe('schema type satisfaction', () => {
  it('discordMessageShape produces valid MessageData structure', () => {
    const msg = {
      content: 'Hello',
      username: 'Bot',
      avatar_url: 'https://example.com/avatar.png',
      embeds: [{ title: 'Embed' }],
      components: [makeTextDisplay()],
      flags: 32768,
    };
    const result = discordMessageShape.parse(msg);
    expect(result.content).toBe('Hello');
    expect(result.components).toHaveLength(1);
    expect(result.flags).toBe(32768);
  });
});

// ============================================================
// Tests: aggregate displayable text limit (Zod schema)
// ============================================================

describe('aggregate displayable text limit', () => {
  it('rejects multiple text displays whose sum exceeds 4000', () => {
    const result = discordMessageShape.safeParse({
      components: [makeTextDisplay('x'.repeat(2001)), makeTextDisplay('x'.repeat(2000))],
    });
    expect(result.success).toBe(false);
  });

  it('accepts multiple text displays whose sum is exactly 4000', () => {
    const result = discordMessageShape.safeParse({
      components: [makeTextDisplay('x'.repeat(2000)), makeTextDisplay('x'.repeat(2000))],
    });
    expect(result.success).toBe(true);
  });

  it('counts text displays nested inside sections', () => {
    const result = discordMessageShape.safeParse({
      components: [
        {
          type: 9,
          components: [makeTextDisplay('x'.repeat(3000))],
          accessory: makeThumbnail(),
        },
        makeTextDisplay('x'.repeat(1001)),
      ],
    });
    expect(result.success).toBe(false);
  });

  it('counts text displays nested inside containers', () => {
    const result = discordMessageShape.safeParse({
      components: [
        makeContainer([makeTextDisplay('x'.repeat(3000))]),
        makeTextDisplay('x'.repeat(1001)),
      ],
    });
    expect(result.success).toBe(false);
  });

  it('counts text displays inside sections within containers', () => {
    const section = {
      type: 9,
      components: [makeTextDisplay('x'.repeat(3000))],
      accessory: makeThumbnail(),
    };
    const result = discordMessageShape.safeParse({
      components: [
        makeContainer([section]),
        makeTextDisplay('x'.repeat(1001)),
      ],
    });
    expect(result.success).toBe(false);
  });

  it('still rejects single text display at 4001 (per-field limit)', () => {
    const result = discordMessageShape.safeParse({
      components: [makeTextDisplay('x'.repeat(4001))],
    });
    expect(result.success).toBe(false);
  });

  it('discordMessageImportShape also rejects aggregate > 4000', () => {
    const result = discordMessageImportShape.safeParse({
      components: [makeTextDisplay('x'.repeat(2001)), makeTextDisplay('x'.repeat(2000))],
    });
    expect(result.success).toBe(false);
  });

  it('discordMessageImportShape accepts aggregate exactly 4000', () => {
    const result = discordMessageImportShape.safeParse({
      components: [makeTextDisplay('x'.repeat(2000)), makeTextDisplay('x'.repeat(2000))],
    });
    expect(result.success).toBe(true);
  });
});

// ============================================================
// QA: aggregate limit edge cases and real user scenarios
// ============================================================

describe('QA: aggregate displayable text — edge cases', () => {
  it('counts text spread across many small text displays', () => {
    // User creates 10 text displays each with 401 chars = 4010 total
    const components = Array.from({ length: 10 }, () => makeTextDisplay('x'.repeat(401)));
    const result = discordMessageShape.safeParse({ components });
    expect(result.success).toBe(false);
  });

  it('accepts many small text displays under limit', () => {
    // 10 text displays × 400 chars = 4000 total (exactly at limit)
    const components = Array.from({ length: 10 }, () => makeTextDisplay('x'.repeat(400)));
    const result = discordMessageShape.safeParse({ components });
    expect(result.success).toBe(true);
  });

  it('does not count non-TextDisplay content fields', () => {
    // MediaGallery items, Thumbnails have description fields — these should NOT count
    const components = [
      makeTextDisplay('x'.repeat(3999)),
      {
        type: 12,
        items: [{ media: { url: 'https://example.com/img.png' }, description: 'x'.repeat(5000) }],
      },
    ];
    const result = discordMessageShape.safeParse({ components });
    expect(result.success).toBe(true);
  });

  it('handles mixed V2 + ActionRow: ActionRow text does not count', () => {
    // ActionRow buttons have labels, but labels are NOT TextDisplay content
    const components = [
      makeTextDisplay('x'.repeat(4000)),
      makeActionRow([makeLinkButton({ label: 'x'.repeat(80) })]),
    ];
    const result = discordMessageShape.safeParse({ components });
    expect(result.success).toBe(true);
  });

  it('import shape: filtered components reduce aggregate below limit', () => {
    // Total is 4001 if all components kept, but one is unsupported type
    // After filtering, only the TextDisplay with 2001 remains — under limit
    const result = discordMessageImportShape.safeParse({
      components: [
        makeTextDisplay('x'.repeat(2001)),
        { type: 99, content: 'x'.repeat(2000) }, // unsupported, filtered out
      ],
    });
    expect(result.success).toBe(true);
  });

  it('rejects aggregate via messageShape (nested data validation)', () => {
    // messageShape wraps discordMessageShape in { name, data }
    // Ensure the refinement applies transitively
    const result = messageShape.safeParse({
      name: 'TestMessage',
      data: {
        components: [makeTextDisplay('x'.repeat(2001)), makeTextDisplay('x'.repeat(2000))],
      },
    });
    expect(result.success).toBe(false);
  });

  it('aggregate error has correct path pointing to components', () => {
    const result = discordMessageShape.safeParse({
      components: [makeTextDisplay('x'.repeat(2001)), makeTextDisplay('x'.repeat(2000))],
    });
    expect(result.success).toBe(false);
    if (!result.success) {
      const aggregateIssue = result.error.issues.find(
        (issue) => issue.message.includes('displayable text'),
      );
      expect(aggregateIssue).toBeDefined();
      expect(aggregateIssue!.path).toContain('components');
    }
  });

  it('deeply nested: section-in-container correctly sums', () => {
    // 3 sections × 3 text displays each (max per section) = 9 text displays
    // 9 × 445 = 4005 > 4000
    const makeFullSection = () => ({
      type: 9,
      components: [
        makeTextDisplay('x'.repeat(445)),
        makeTextDisplay('x'.repeat(445)),
        makeTextDisplay('x'.repeat(445)),
      ],
      accessory: makeThumbnail(),
    });
    const result = discordMessageShape.safeParse({
      components: [
        makeContainer([makeFullSection(), makeFullSection(), makeFullSection()]),
      ],
    });
    expect(result.success).toBe(false);
  });
});

describe('discordMessageShape description bound', () => {
  const long = 'a'.repeat(1025);
  const galleryWith = (description: string) => ({
    type: 12, items: [{ media: { url: 'https://example.com/a.png' }, description }],
  });

  it('saves a Thumbnail description longer than 1024 characters', () => {
    const result = discordMessageShape.safeParse({
      components: [makeSection({ ...makeThumbnail(), description: long })],
    });
    expect(result.success).toBe(true);
  });

  it('saves a gallery item description longer than 1024 characters', () => {
    const result = discordMessageShape.safeParse({ components: [galleryWith(long)] });
    expect(result.success).toBe(true);
  });
});

