  makeLinkButton, makeActionRow, makeTextDisplay, makeThumbnail, makeSection,
  makeMediaGallery, makeFile, makeSeparator, makeContainer,
} from '~/utils/__tests__/helpers/components';

// ============================================================
// collectKeys: recursively extract all _key values
// ============================================================

function collectKeys(obj: unknown): string[] {
  const keys: string[] = [];
  if (obj && typeof obj === 'object') {
    if ('_key' in (obj as Record<string, unknown>)) {
      keys.push((obj as Record<string, unknown>)._key as string);
    }
    for (const value of Object.values(obj as Record<string, unknown>)) {
      if (Array.isArray(value)) {
        for (const item of value) keys.push(...collectKeys(item));
      } else if (value && typeof value === 'object') {
        keys.push(...collectKeys(value));
      }
    }
  }
  return keys;
}

function hasAnyKey(obj: unknown): boolean {
  return collectKeys(obj).length > 0;
}

// ============================================================
// Tests: injectComponentKeys
// ============================================================

describe('injectComponentKeys', () => {
  it('adds _key to a simple text display', () => {
    const result = injectComponentKeys(makeTextDisplay());
    expect(result).toHaveProperty('_key');
    expect(typeof result._key).toBe('string');
    expect(result._key.length).toBeGreaterThan(0);
  });

  it('adds _key to action row and its child buttons', () => {
    const result = injectComponentKeys(makeActionRow([makeLinkButton(), makeLinkButton()]));
    expect(result).toHaveProperty('_key');
    const row = result as { _key: string, components: { _key: string }[] };
    expect(row.components).toHaveLength(2);
    for (const btn of row.components) {
      expect(btn).toHaveProperty('_key');
    }
  });

  it('adds _key to section, its text children, and accessory', () => {
    const result = injectComponentKeys(makeSection(2, 'thumbnail'));
    const sec = result as {
      _key: string;
      components: { _key: string }[];
      accessory: { _key: string };
    };
    expect(sec._key).toBeDefined();
    expect(sec.components).toHaveLength(2);
    for (const child of sec.components) {
      expect(child._key).toBeDefined();
    }
    expect(sec.accessory._key).toBeDefined();
  });

  it('adds _key to section with link button accessory', () => {
    const result = injectComponentKeys(makeSection(1, 'button'));
    const sec = result as { accessory: { _key: string, type: number } };
    expect(sec.accessory._key).toBeDefined();
    expect(sec.accessory.type).toBe(2);
  });

  it('adds _key to media gallery items', () => {
    const result = injectComponentKeys(makeMediaGallery(3));
    const mg = result as { _key: string, items: { _key: string }[] };
    expect(mg._key).toBeDefined();
    expect(mg.items).toHaveLength(3);
    for (const item of mg.items) {
      expect(item._key).toBeDefined();
    }
  });

  it('adds _key to file component', () => {
    const result = injectComponentKeys(makeFile());
    expect(result._key).toBeDefined();
  });

  it('adds _key to separator component', () => {
    const result = injectComponentKeys(makeSeparator());
    expect(result._key).toBeDefined();
  });

  it('recursively injects keys into container children', () => {
    const container = makeContainer([
      makeTextDisplay(),
      makeActionRow([makeLinkButton(), makeLinkButton()]),
      makeSection(1, 'thumbnail'),
    ]);
    const result = injectComponentKeys(container);
    const keys = collectKeys(result);
    // Container(1) + TextDisplay(1) + ActionRow(1) + 2 buttons(2) + Section(1) + text(1) + accessory(1) = 8
    expect(keys.length).toBe(8);
    // All keys should be unique
    expect(new Set(keys).size).toBe(keys.length);
  });

  it('does not mutate the input object', () => {
    const original = makeTextDisplay();
    const originalStr = JSON.stringify(original);
    injectComponentKeys(original);
    expect(JSON.stringify(original)).toBe(originalStr);
  });

  it('preserves existing _key values', () => {
    const component = { ...makeTextDisplay(), _key: 'existing-key' };
    const result = injectComponentKeys(component);
    expect(result._key).toBe('existing-key');
  });
});

// ============================================================
// Tests: rekeyComponent
// ============================================================

describe('rekeyComponent', () => {
  it('generates new _key for a simple component', () => {
    const original = injectComponentKeys(makeTextDisplay());
    const rekeyed = rekeyComponent(original);
    expect(rekeyed._key).not.toBe(original._key);
  });

  it('generates all-new keys for a container with nested children', () => {
    const container = injectComponentKeys(makeContainer([
      makeTextDisplay(),
      makeActionRow([makeLinkButton(), makeLinkButton()]),
      makeSection(2, 'thumbnail'),
    ]));
    const originalKeys = collectKeys(container);
    const rekeyed = rekeyComponent(container);
    const newKeys = collectKeys(rekeyed);

    // Same structure → same number of keys
    expect(newKeys.length).toBe(originalKeys.length);

    // No overlap between original and new keys
    for (const nk of newKeys) {
      expect(originalKeys).not.toContain(nk);
    }

    // All new keys are unique
    expect(new Set(newKeys).size).toBe(newKeys.length);
  });

  it('preserves data values while changing keys', () => {
    const original = injectComponentKeys(makeTextDisplay('Important content'));
    const rekeyed = rekeyComponent(original);
    expect((rekeyed as { content: string }).content).toBe('Important content');
    expect((rekeyed as { type: number }).type).toBe(10);
  });

  it('does not mutate the original component', () => {
    const original = injectComponentKeys(makeTextDisplay());
    const originalKey = original._key;
    rekeyComponent(original);
    expect(original._key).toBe(originalKey);
  });
});

// ============================================================
// Tests: stripKeys (& stripComponentKeys indirectly)
// ============================================================

describe('stripKeys', () => {
  it('removes _key from embeds and embed fields', () => {
    const message = {
      data: {
        embeds: [{
          _key: 'e1',
          title: 'Hello',
          fields: [
            { _key: 'f1', name: 'Field 1', value: 'Value 1' },
            { _key: 'f2', name: 'Field 2', value: 'Value 2' },
          ],
        }],
      },
    };
    const result = stripKeys(message);
    expect(result.data.embeds![0]).not.toHaveProperty('_key');
    for (const field of result.data.embeds![0].fields!) {
      expect(field).not.toHaveProperty('_key');
    }
  });

  it('removes _key from all component types recursively', () => {
    const components = [
      injectComponentKeys(makeActionRow([makeLinkButton(), makeLinkButton()])),
      injectComponentKeys(makeTextDisplay()),
      injectComponentKeys(makeSection(2, 'thumbnail')),
      injectComponentKeys(makeMediaGallery(2)),
      injectComponentKeys(makeFile()),
      injectComponentKeys(makeSeparator()),
      injectComponentKeys(makeContainer([
        makeTextDisplay(),
        makeSection(1, 'button'),
      ])),
    ];
    const message = { data: { components } };
    const result = stripKeys(message);

    // No _key should remain anywhere
    expect(hasAnyKey(result.data.components)).toBe(false);
  });

  it('sets IS_COMPONENTS_V2_FLAG when V2 components are present', () => {
    const components = [
      injectComponentKeys(makeTextDisplay()),
    ];
    const message = { data: { components } };
    const result = stripKeys(message);
    expect(result.data.flags).toBeDefined();
    expect(result.data.flags! & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);
  });

  it('sets IS_COMPONENTS_V2_FLAG value to 32768', () => {
    expect(IS_COMPONENTS_V2_FLAG).toBe(32768);
    expect(IS_COMPONENTS_V2_FLAG).toBe(1 << 15);
  });

  it('preserves existing flags when adding V2 flag', () => {
    const existingFlags = 4; // some other flag
    const components = [injectComponentKeys(makeTextDisplay())];
    const message = { data: { components, flags: existingFlags } };
    const result = stripKeys(message);
    expect(result.data.flags! & existingFlags).toBe(existingFlags);
    expect(result.data.flags! & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);
  });

  it('does NOT set V2 flag for action-row-only messages (type 1 is not V2)', () => {
    const components = [
      injectComponentKeys(makeActionRow([makeLinkButton()])),
    ];
    const message = { data: { components } };
    const result = stripKeys(message);
    // V2_COMPONENT_TYPES = {9,10,11,12,13,14,17} — type 1 is NOT in this set
    expect(result.data.flags ?? 0).toBe(0);
  });

  it('sets V2 flag when mixing action rows with V2 components', () => {
    const components = [
      injectComponentKeys(makeActionRow([makeLinkButton()])),
      injectComponentKeys(makeTextDisplay()),
    ];
    const message = { data: { components } };
    const result = stripKeys(message);
    expect(result.data.flags! & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);
  });

  it('handles message with no components', () => {
    const message = { data: { content: 'Hello' } };
    const result = stripKeys(message);
    expect(result.data.content).toBe('Hello');
    expect(result.data.flags).toBeUndefined();
  });

  it('handles message with empty components array', () => {
    const message = { data: { components: [] as EditableTopLevelComponent[] } };
    const result = stripKeys(message);
    expect(result.data.components).toEqual([]);
  });

  it('does not mutate the input message', () => {
    const components = [injectComponentKeys(makeTextDisplay())];
    const message = { data: { components } };
    const originalStr = JSON.stringify(message);
    stripKeys(message);
    expect(JSON.stringify(message)).toBe(originalStr);
  });
});

// ============================================================
// Tests: makeEditable
// ============================================================

describe('makeEditable', () => {
  it('injects _key into embeds and fields', () => {
    const apiMessage = {
      name: 'Test',
      updatedAt: Date.now(),
      data: {
        embeds: [{
          title: 'Test',
          fields: [{ name: 'F', value: 'V' }],
        }],
      },
    };
    const result = makeEditable(apiMessage);
    expect(result.data.embeds![0]._key).toBeDefined();
    expect(result.data.embeds![0].fields![0]._key).toBeDefined();
  });

  it('injects _key into components recursively', () => {
    const apiMessage = {
      name: 'Test',
      updatedAt: Date.now(),
      data: {
        components: [
          makeTextDisplay(),
          makeContainer([makeSection(1, 'thumbnail')]),
        ],
      },
    };
    const result = makeEditable(apiMessage as Partial<ApiMessage>);
    const keys = collectKeys(result.data.components);
    // TextDisplay(1) + Container(1) + Section(1) + text(1) + accessory(1) = 5
    expect(keys.length).toBe(5);
    expect(new Set(keys).size).toBe(keys.length);
  });

  it('deep clones the input (does not share references)', () => {
    const apiMessage = {
      name: 'Test',
      updatedAt: Date.now(),
      data: {
        content: 'Hello',
        components: [makeTextDisplay()],
      },
    };
    const result = makeEditable(apiMessage);
    result.data.content = 'Modified';
    expect(apiMessage.data.content).toBe('Hello');
  });
});

// ============================================================
// Tests: Roundtrip (inject → edit → strip)
// ============================================================

describe('roundtrip: injectComponentKeys → stripKeys', () => {
  it('roundtrip preserves data for every V2 component type', () => {
    const original = {
      data: {
        content: 'Hello world',
        embeds: [{ title: 'Embed title' }],
        components: [
          makeActionRow([makeLinkButton({ label: 'Link 1' }), makeLinkButton({ label: 'Link 2' })]),
          makeTextDisplay('Some text'),
          makeSection(2, 'thumbnail'),
          makeMediaGallery(3),
          makeFile('https://example.com/doc.pdf'),
          makeSeparator(),
          makeContainer([
            makeTextDisplay('Container text'),
            makeSeparator(),
            makeActionRow([makeLinkButton()]),
          ]),
        ],
      },
    };

    // Simulate makeEditable (inject keys)
    const editable = makeEditable({ name: 'Test', updatedAt: Date.now(), ...original } as Partial<ApiMessage>);

    // Verify keys are present
    const keys = collectKeys(editable.data.components);
    expect(keys.length).toBeGreaterThan(0);

    // Strip keys (simulating save/send)
    const stripped = stripKeys(editable);

    // No _key should remain
    expect(hasAnyKey(stripped.data.components)).toBe(false);

    // V2 flag should be set (has TextDisplay, Section, etc.)
    expect(stripped.data.flags! & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);

    // Data integrity: check a few values survived
    // The serialiser does not delete content/embeds under V2 — that choice belongs to the
    // persisting writer, not the serialiser.
    expect(stripped.data.content).toBe('Hello world');
    expect(stripped.data.embeds?.[0]).toMatchObject({ title: 'Embed title' });
    const firstRow = stripped.data.components![0] as { components: { label: string }[] };
    expect(firstRow.components[0].label).toBe('Link 1');
    const textDisplay = stripped.data.components![1] as { content: string };
    expect(textDisplay.content).toBe('Some text');
  });

  it('roundtrip works for empty message', () => {
    const editable = makeEditable({ name: 'Empty', updatedAt: Date.now(), data: {} });
    const stripped = stripKeys(editable);
    expect(stripped.data.components).toBeUndefined();
    expect(stripped.data.flags).toBeUndefined();
  });
});

// ============================================================
// Tests: Constants
// ============================================================

describe('constants', () => {
  it('MAX_TOTAL_COMPONENTS is 40', () => {
    expect(MAX_TOTAL_COMPONENTS).toBe(40);
  });

  it('IS_COMPONENTS_V2_FLAG is 32768 (1 << 15)', () => {
    expect(IS_COMPONENTS_V2_FLAG).toBe(32768);
  });
});

// ============================================================
// Tests: genUuid produces unique values
// ============================================================

describe('genUuid', () => {
  it('produces unique values on successive calls', () => {
    const uuids = new Set(Array.from({ length: 100 }, () => genUuid()));
    expect(uuids.size).toBe(100);
  });
});

