import { describe, it, expect, vi } from 'vitest';

// Mock env.mjs to prevent environment variable validation at import time
vi.mock('~/env.mjs', () => ({
  env: {
    NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test',
  },
}));

vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import { genUuid, rekeyComponent } from '~/utils';
import {
  MAX_SECTION_TEXT_COMPONENTS,
  MAX_ACTION_ROW_BUTTONS,
  MAX_MEDIA_GALLERY_ITEMS,
} from '~/constants';

// ============================================================
// Shared fixtures
// ============================================================

function makeEditableTextDisplay(content = 'Hello'): EditableTextDisplay {
  return { type: 10, content, _key: genUuid() } as EditableTextDisplay;
}

function makeEditableLinkButton(label = 'Click'): EditableLinkButton {
  return {
    type: 2, style: 5, url: 'https://example.com', label, _key: genUuid(),
  } as EditableLinkButton;
}

function makeEditableThumbnail(): EditableThumbnail {
  return {
    type: 11, media: { url: 'https://example.com/img.png' }, _key: genUuid(),
  } as EditableThumbnail;
}

function makeEditableSection(textCount = 1): EditableSection {
  return {
    type: 9,
    components: Array.from({ length: textCount }, (_, i) => makeEditableTextDisplay(`Text ${i}`)),
    accessory: makeEditableThumbnail(),
    _key: genUuid(),
  } as EditableSection;
}

function makeEditableMediaGalleryItem(opts?: {
  url?: string;
  description?: string;
  spoiler?: boolean;
}): EditableMediaGalleryItem {
  return {
    media: { url: opts?.url ?? 'https://example.com/img.png' },
    description: opts?.description,
    spoiler: opts?.spoiler,
    _key: genUuid(),
  } as EditableMediaGalleryItem;
}

// ============================================================
// Duplicate at last index (edge case)
// ============================================================

describe('Duplicate at last index', () => {
  it('duplicates text display at last index — clone placed at end', () => {
    const section = makeEditableSection(2);
    const lastIdx = section.components.length - 1;
    const original = section.components[lastIdx];

    const clone: EditableTextDisplay = { ...original, _key: genUuid() };
    const next = [...section.components];
    next.splice(lastIdx + 1, 0, clone);

    expect(next).toHaveLength(3);
    expect(next[0]).toBe(section.components[0]);
    expect(next[1]).toBe(original);
    expect(next[2].content).toBe(original.content);
    expect(next[2]._key).not.toBe(original._key);
  });

  it('duplicates button at last index — clone placed at end', () => {
    const buttons = [makeEditableLinkButton('A'), makeEditableLinkButton('B')];
    const lastIdx = buttons.length - 1;
    const original = buttons[lastIdx];

    const clone: EditableLinkButton = { ...original, _key: genUuid() };
    const next = [...buttons];
    next.splice(lastIdx + 1, 0, clone);

    expect(next).toHaveLength(3);
    expect(next[0]).toBe(buttons[0]);
    expect(next[1]).toBe(original);
    expect(next[2].label).toBe('B');
    expect(next[2]._key).not.toBe(original._key);
  });

  it('duplicates media gallery item at last index — clone placed at end', () => {
    const items = [makeEditableMediaGalleryItem(), makeEditableMediaGalleryItem({ url: 'https://last.png' })];
    const lastIdx = items.length - 1;
    const original = items[lastIdx];

    const clone: EditableMediaGalleryItem = { ...original, _key: genUuid() };
    const next = [...items];
    next.splice(lastIdx + 1, 0, clone);

    expect(next).toHaveLength(3);
    expect(next[2].media.url).toBe('https://last.png');
    expect(next[2]._key).not.toBe(original._key);
  });
});

// ============================================================
// Content field preservation on duplicate
// ============================================================

describe('Content field preservation on duplicate', () => {
  it('text display clone preserves content exactly', () => {
    const original = makeEditableTextDisplay('Hello **world** with `code`');
    const clone: EditableTextDisplay = { ...original, _key: genUuid() };

    expect(clone.content).toBe('Hello **world** with `code`');
    expect(clone.type).toBe(10);
    expect(clone._key).not.toBe(original._key);
  });

  it('link button clone preserves all fields (label, url, emoji, disabled, style)', () => {
    const original: EditableLinkButton = {
      type: 2,
      style: 5,
      url: 'https://hooks.gg',
      label: 'Visit',
      emoji: { name: '🔗' },
      disabled: true,
      _key: genUuid(),
    } as EditableLinkButton;

    const clone: EditableLinkButton = { ...original, _key: genUuid() };

    expect(clone.label).toBe('Visit');
    expect(clone.url).toBe('https://hooks.gg');
    expect(clone.emoji?.name).toBe('🔗');
    expect(clone.disabled).toBe(true);
    expect(clone.style).toBe(5);
    expect(clone._key).not.toBe(original._key);
  });

  it('media gallery item clone preserves url, description, and spoiler', () => {
    const original = makeEditableMediaGalleryItem({
      url: 'https://img.example.com/photo.jpg',
      description: 'A beautiful sunset',
      spoiler: true,
    });

    const clone: EditableMediaGalleryItem = { ...original, _key: genUuid() };

    expect(clone.media.url).toBe('https://img.example.com/photo.jpg');
    expect(clone.description).toBe('A beautiful sunset');
    expect(clone.spoiler).toBe(true);
    expect(clone._key).not.toBe(original._key);
  });

  it('media gallery item clone without optional fields preserves undefined', () => {
    const original = makeEditableMediaGalleryItem({ url: 'https://img.png' });

    const clone: EditableMediaGalleryItem = { ...original, _key: genUuid() };

    expect(clone.description).toBeUndefined();
    expect(clone.spoiler).toBeUndefined();
  });
});

// ============================================================
// Container child deep clone — accessory key verification
// ============================================================

describe('Container child deep clone completeness', () => {
  it('rekeyComponent re-keys the accessory of a Section', () => {
    const section = makeEditableSection(1);
    const originalAccessoryKey = section.accessory._key;

    const cloned = rekeyComponent(
      section as EditableTopLevelComponent,
    ) as EditableSection;

    expect(cloned.accessory._key).not.toBe(originalAccessoryKey);
    expect((cloned.accessory as EditableThumbnail).media.url)
      .toBe((section.accessory as EditableThumbnail).media.url);
  });

  it('rekeyComponent produces entirely unique keys for deep Section', () => {
    const section = makeEditableSection(3);
    const originalKeys = new Set([
      section._key,
      ...section.components.map((c) => c._key),
      section.accessory._key,
    ]);

    const cloned = rekeyComponent(
      section as EditableTopLevelComponent,
    ) as EditableSection;

    const clonedKeys = [
      cloned._key,
      ...cloned.components.map((c) => c._key),
      cloned.accessory._key,
    ];

    // Every cloned key must be different from every original key
    for (const key of clonedKeys) {
      expect(originalKeys.has(key)).toBe(false);
    }

    // All cloned keys must be unique among themselves
    expect(new Set(clonedKeys).size).toBe(clonedKeys.length);
  });

  it('rekeyComponent preserves text content of all children', () => {
    const section = makeEditableSection(3);
    const originalContents = section.components.map((c) => c.content);

    const cloned = rekeyComponent(
      section as EditableTopLevelComponent,
    ) as EditableSection;

    cloned.components.forEach((c, i) => {
      expect(c.content).toBe(originalContents[i]);
    });
  });
});

// ============================================================
// Gating edge cases
// ============================================================

describe('Gating edge cases', () => {
  it('section with 1 text display: duplicate IS offered (1 < 3)', () => {
    const section = makeEditableSection(1);
    expect(section.components.length < MAX_SECTION_TEXT_COMPONENTS).toBe(true);
  });

  it('section with 2 text displays: duplicate IS offered (2 < 3)', () => {
    const section = makeEditableSection(2);
    expect(section.components.length < MAX_SECTION_TEXT_COMPONENTS).toBe(true);
  });

  it('action row with 1 button: duplicate IS offered (1 < 5)', () => {
    const buttons = [makeEditableLinkButton()];
    expect(buttons.length < MAX_ACTION_ROW_BUTTONS).toBe(true);
  });

  it('action row with 4 buttons: duplicate IS offered (4 < 5)', () => {
    const buttons = Array.from({ length: 4 }, () => makeEditableLinkButton());
    expect(buttons.length < MAX_ACTION_ROW_BUTTONS).toBe(true);
  });

  it('media gallery with 9 items: duplicate IS offered (9 < 10)', () => {
    const items = Array.from({ length: 9 }, () => makeEditableMediaGalleryItem());
    expect(items.length < MAX_MEDIA_GALLERY_ITEMS).toBe(true);
  });
});

// ============================================================
// Move preserves all elements (no data loss)
// ============================================================

describe('Move operations preserve all elements', () => {
  it('move up preserves array length and all elements', () => {
    const section = makeEditableSection(3);
    const originalKeys = section.components.map((c) => c._key);
    const idx = 2;

    const next = [...section.components];
    [next[idx - 1], next[idx]] = [next[idx], next[idx - 1]];

    expect(next).toHaveLength(3);
    const resultKeys = next.map((c) => c._key);
    // All original keys still present
    expect(resultKeys.sort()).toEqual(originalKeys.sort());
  });

  it('move down preserves array length and all elements', () => {
    const section = makeEditableSection(3);
    const originalKeys = section.components.map((c) => c._key);
    const idx = 0;

    const next = [...section.components];
    [next[idx], next[idx + 1]] = [next[idx + 1], next[idx]];

    expect(next).toHaveLength(3);
    const resultKeys = next.map((c) => c._key);
    expect(resultKeys.sort()).toEqual(originalKeys.sort());
  });
});

// ============================================================
// Delete middle element preserves order of others
// ============================================================

describe('Delete preserves order of remaining elements', () => {
  it('deleting middle text display preserves first and last in order', () => {
    const section = makeEditableSection(3);
    const first = section.components[0];
    const last = section.components[2];

    const result = section.components.filter((_, i) => i !== 1);

    expect(result).toHaveLength(2);
    expect(result[0]).toBe(first);
    expect(result[1]).toBe(last);
  });

  it('deleting first text display shifts others up', () => {
    const section = makeEditableSection(3);
    const second = section.components[1];
    const third = section.components[2];

    const result = section.components.filter((_, i) => i !== 0);

    expect(result).toHaveLength(2);
    expect(result[0]).toBe(second);
    expect(result[1]).toBe(third);
  });

  it('deleting last text display preserves first and second', () => {
    const section = makeEditableSection(3);
    const first = section.components[0];
    const second = section.components[1];

    const result = section.components.filter((_, i) => i !== 2);

    expect(result).toHaveLength(2);
    expect(result[0]).toBe(first);
    expect(result[1]).toBe(second);
  });
});

