describe('EXT-2 — nested V2 under a non-V2 top level is NOT REPRESENTABLE', () => {
  // The gate, `hasV2Components`, and this file's predicate all detect V2-ness at TOP LEVEL ONLY.
  // That is sound — but by the shape of the real schema, exercised here rather than read as text:
  //   - the ONLY non-V2 top-level type accepted by `topLevelComponentShape` is the Action Row
  //     (type 1); every other member of the union is itself a V2 type;
  //   - the Action Row's own `components` field rejects a V2-typed child in place of a link
  //     button.
  //
  // widen — select menus, or a general container — the schema AND the gate's predicate inherit the
  // hole together and this test catches it, because both cases exercise the live schema.

  it('every top-level type other than the Action Row is itself a V2 type', () => {
    const v2Types = new Set<number>(V2_COMPONENT_TYPE_VALUES);
    const topLevelTypes = topLevelComponentShape.options.map(
      (option) => (option.shape.type as z.ZodLiteral<number>).value,
    );
    expect(topLevelTypes.filter((t) => t !== 1 && !v2Types.has(t))).toEqual([]);
  });

  it('FALSIFIER — the Action Row schema rejects a V2 component in place of a link button', () => {
    // If this goes red, `actionRowShape` has widened to admit a V2-typed child, and
    // `hasV2Components` must stop being top-level-only — in `limits.tsx`, in `hasV2Components`,
    // and in this file's predicate, all three.
    const result = topLevelComponentShape.safeParse({
      type: 1,
