import { IS_COMPONENTS_V2_FLAG } from '~/constants';
import {
  isMessageV2, detectMessageMode, showV2PatchWarning, switchToV2, switchToClassic,
} from '~/utils/messageMode';

describe('isMessageV2, the shared mode predicate', () => {
  it('is true when the V2 flag bit is set, with no components at all', () => {
    expect(isMessageV2({ flags: IS_COMPONENTS_V2_FLAG })).toBe(true);
  });

  it('is true when the V2 flag bit is set over Action-Rows-only components', () => {
    expect(isMessageV2({
      flags: IS_COMPONENTS_V2_FLAG,
      components: [{ type: 1, components: [] }],
    })).toBe(true);
  });

  it('is true when V2 components are present with no flag (row B) — isolates the structural conjunct', () => {
    expect(isMessageV2({ components: [{ type: 17, components: [] }] })).toBe(true);
  });

  it('is false when neither the flag nor V2 components are present', () => {
    expect(isMessageV2({ content: 'hi' } as never)).toBe(false);
    expect(isMessageV2({})).toBe(false);
  });
});

describe('detectMessageMode reads the flag regardless of components presence', () => {
  it('returns v2 for a flag-only record with no `components` key (5712-shaped)', () => {
    expect(detectMessageMode({ data: { flags: IS_COMPONENTS_V2_FLAG, content: 'hi' } } as never)).toBe('v2');
  });

  it('returns v2 for structural V2 components with no flag', () => {
    expect(detectMessageMode({
      data: { components: [{ type: 17, components: [] }] },
    } as never)).toBe('v2');
  });

  it('returns classic for an ordinary classic message', () => {
    expect(detectMessageMode({ data: { content: 'hi' } } as never)).toBe('classic');
  });

  it('returns null (no mode set) when there is no message', () => {
    expect(detectMessageMode(null)).toBe(null);
  });
});

describe('the toggle sets what it shows', () => {
  it('switchToV2 sets IS_COMPONENTS_V2_FLAG, mirroring switchToClassic clearing it', () => {
    const result = switchToV2({ flags: 0, content: 'hi', embeds: [] });
    expect(result.flags).toBe(IS_COMPONENTS_V2_FLAG);
  });

  it('switchToV2 preserves other bits already set in flags', () => {
    const SUPPRESS_NOTIFICATIONS = 4096;
    const result = switchToV2({ flags: SUPPRESS_NOTIFICATIONS });
    expect(result.flags).toBe(SUPPRESS_NOTIFICATIONS | IS_COMPONENTS_V2_FLAG);
  });

  it('switchToClassic still clears the bit and preserves other bits', () => {
    const SUPPRESS_NOTIFICATIONS = 4096;
    const result = switchToClassic({ flags: IS_COMPONENTS_V2_FLAG | SUPPRESS_NOTIFICATIONS, components: [] });
    expect(result.flags).toBe(SUPPRESS_NOTIFICATIONS);
  });

  it('a V2-mode draft with only Action Rows, saved and reloaded, opens in V2 (misreport cannot occur)', () => {
    const draftAfterSwitch = switchToV2({ flags: 0, components: [{ type: 1, components: [] }] });
    expect(detectMessageMode({ data: draftAfterSwitch } as never)).toBe('v2');
  });
});

describe('showV2PatchWarning, the extracted predicate', () => {
  it('warns when editing (showEdit) an already-sent message (oldMessage) that is V2 by flag alone', () => {
    const message = { data: { flags: IS_COMPONENTS_V2_FLAG, components: [{ type: 1, components: [] }] } };
    expect(showV2PatchWarning(message as never, { id: '123' } as never, true)).toBe(true);
  });

  it('does not warn when not editing an existing send (showEdit false)', () => {
    const message = { data: { flags: IS_COMPONENTS_V2_FLAG } };
    expect(showV2PatchWarning(message as never, { id: '123' } as never, false)).toBe(false);
  });

  it('does not warn when there is no prior sent message (oldMessage null)', () => {
    const message = { data: { flags: IS_COMPONENTS_V2_FLAG } };
    expect(showV2PatchWarning(message as never, null, true)).toBe(false);
  });

  it('does not warn for a classic message being edited', () => {
    const message = { data: { content: 'hi' } };
    expect(showV2PatchWarning(message as never, { id: '123' } as never, true)).toBe(false);
  });
});

