import {
  describe, it, expect, vi,
} from 'vitest';

import {
  hasV2Components,
  hasClassicContent,
  hasV2Content,
  stripKeys,
  injectComponentKeys,
} from '~/utils';
import { validateMessage, validateDisplayableTextCount } from '~/utils/limits';
import { IS_COMPONENTS_V2_FLAG } from '~/constants';

// Mock env.mjs to prevent environment variable validation at import time
vi.mock('~/env.mjs', () => ({
  env: {
    NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test',
  },
}));

// Mock SVG components imported by utils/index.ts
vi.mock('~/assets/svg/TextIcon', () => ({ default: {} }));
vi.mock('~/assets/svg/VoiceIcon', () => ({ default: {} }));

import {
  makeLinkButton, makeActionRow, makeTextDisplay, makeThumbnail, makeSection,
  makeContainer, makeSeparator,
} from '~/utils/__tests__/helpers/components';

// ============================================================
// Tests: hasV2Components
// ============================================================

describe('hasV2Components', () => {
  it('returns true when components contain V2 type (TextDisplay)', () => {
    expect(hasV2Components([makeTextDisplay()])).toBe(true);
  });

  it('returns true for Section (type 9)', () => {
    expect(hasV2Components([makeSection()])).toBe(true);
  });

  it('returns true for Container (type 17)', () => {
    expect(hasV2Components([makeContainer()])).toBe(true);
  });

  it('returns true for Separator (type 14)', () => {
    expect(hasV2Components([makeSeparator()])).toBe(true);
  });

  it('returns false for legacy ActionRow only (type 1)', () => {
    expect(hasV2Components([makeActionRow()])).toBe(false);
  });

  it('returns false for empty array', () => {
    expect(hasV2Components([])).toBe(false);
  });

  it('returns false for undefined', () => {
    expect(hasV2Components(undefined)).toBe(false);
  });

  it('returns true when mixing ActionRow + V2 types', () => {
    expect(hasV2Components([makeActionRow(), makeTextDisplay()])).toBe(true);
  });
});

// ============================================================
// Tests: hasClassicContent
// ============================================================

describe('hasClassicContent', () => {
  it('returns true when content is non-empty', () => {
    expect(hasClassicContent({ content: 'hello' })).toBe(true);
  });

  it('returns true when embeds array has entries', () => {
    expect(hasClassicContent({ embeds: [{ title: 'Test' }] })).toBe(true);
  });

  it('returns true when both content and embeds exist', () => {
    expect(hasClassicContent({ content: 'hello', embeds: [{ title: 'T' }] })).toBe(true);
  });

  it('returns false for empty content and no embeds', () => {
    expect(hasClassicContent({ content: '' })).toBe(false);
  });

  it('returns false for empty content and empty embeds', () => {
    expect(hasClassicContent({ content: '', embeds: [] })).toBe(false);
  });

  it('returns false for undefined content and embeds', () => {
    expect(hasClassicContent({})).toBe(false);
  });

  it('returns false for whitespace-only content', () => {
    expect(hasClassicContent({ content: '   ' })).toBe(false);
  });
});

// ============================================================
// Tests: hasV2Content
// ============================================================

describe('hasV2Content', () => {
  it('returns true when components have V2 types', () => {
    expect(hasV2Content([makeTextDisplay()])).toBe(true);
  });

  it('returns false when only legacy ActionRows exist', () => {
    expect(hasV2Content([makeActionRow()])).toBe(false);
  });

  it('returns false for empty array', () => {
    expect(hasV2Content([])).toBe(false);
  });

  it('returns false for undefined', () => {
    expect(hasV2Content(undefined)).toBe(false);
  });

  it('returns true for Container type (17)', () => {
    expect(hasV2Content([makeContainer()])).toBe(true);
  });
});

// ============================================================
// Tests: stripKeys does not delete content/embeds under V2
// ============================================================
// No serialiser on the persist/seed/hash paths may remove content or embeds on its own — that
// choice belongs to the persisting writer (gateBeforePersist + the user's choice), not the
// serialiser. stripKeys is identity-modulo-`_key`s plus the V2 bit set from structure, over every
// input.

describe('stripKeys retains embeds/content under V2 components', () => {
  it('keeps embeds when V2 components are present', () => {
    const message = {
      data: {
        embeds: [{ title: 'Kept' }],
        components: [injectComponentKeys(makeTextDisplay())] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.embeds![0]).toMatchObject({ title: 'Kept' });
  });

  it('keeps content when V2 components are present', () => {
    const message = {
      data: {
        content: 'Kept',
        components: [injectComponentKeys(makeTextDisplay())] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.content).toBe('Kept');
  });

  it('keeps both embeds and content when V2 components are present, and still sets the bit', () => {
    const message = {
      data: {
        content: 'text',
        embeds: [{ title: 'embed' }],
        components: [injectComponentKeys(makeContainer([makeTextDisplay()]))] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.embeds![0]).toMatchObject({ title: 'embed' });
    expect(result.data.content).toBe('text');
    expect(result.data.flags! & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);
  });

  it('does NOT strip embeds/content when only legacy ActionRows present', () => {
    const message = {
      data: {
        content: 'Keep this',
        embeds: [{ title: 'Keep this too' }],
        components: [injectComponentKeys(makeActionRow())] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.content).toBe('Keep this');
    expect(result.data.embeds![0].title).toBe('Keep this too');
  });

  it('does NOT strip embeds/content when no components present', () => {
    const message = {
      data: {
        content: 'Keep',
        embeds: [{ title: 'Also keep' }],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.content).toBe('Keep');
    expect(result.data.embeds![0].title).toBe('Also keep');
  });

  it('preserves components, flags, content and embeds together', () => {
    const message = {
      data: {
        content: 'keep',
        embeds: [{ title: 'keep too' }],
        components: [injectComponentKeys(makeTextDisplay('keep'))] as EditableTopLevelComponent[],
      },
    };
    const result = stripKeys(message as { data: EditableMessageData });
    expect(result.data.components).toHaveLength(1);
    expect((result.data.components![0] as { content: string }).content).toBe('keep');
    expect(result.data.flags! & IS_COMPONENTS_V2_FLAG).toBe(IS_COMPONENTS_V2_FLAG);
    expect(result.data.content).toBe('keep');
    expect(result.data.embeds![0]).toMatchObject({ title: 'keep too' });
  });
});

// ============================================================
// Tests: validateMessage mutual exclusivity
// ============================================================

describe('validateMessage mutual exclusivity', () => {
  it('returns error string for message with V2 components AND embeds', () => {
    const data = {
      content: '',
      username: 'TestUser',
      embeds: [{ title: 'Embed' }],
      components: [makeTextDisplay()],
    } as unknown as MessageData;
    const result = validateMessage(data);
    expect(typeof result).toBe('string');
    expect((result as string).length).toBeGreaterThan(0);
  });

  it('returns error string for message with V2 components AND content', () => {
    const data = {
      content: 'Hello',
      username: 'TestUser',
      embeds: [],
      components: [makeTextDisplay()],
    } as unknown as MessageData;
    const result = validateMessage(data);
    expect(typeof result).toBe('string');
    expect((result as string).length).toBeGreaterThan(0);
  });

  it('returns empty string for V2 components without content/embeds (valid)', () => {
    const data = {
      content: '',
      username: 'TestUser',
      embeds: [],
      components: [makeTextDisplay()],
    } as unknown as MessageData;
    const result = validateMessage(data);
    expect(result).toBe('');
  });

  it('returns empty string for classic message (embeds + content, no V2)', () => {
    const data = {
      content: 'Hello',
      username: 'TestUser',
      embeds: [{ title: 'Test' }],
      components: [],
    } as unknown as MessageData;
    const result = validateMessage(data);
    expect(result).toBe('');
  });

  it('returns empty string for legacy ActionRow + embeds (not V2)', () => {
    const data = {
      content: '',
      username: 'TestUser',
      embeds: [{ title: 'Test' }],
      components: [makeActionRow()],
    } as unknown as MessageData;
    const result = validateMessage(data);
    expect(result).toBe('');
  });

  it('returns error for no content, no embeds, no components', () => {
    const data = {
      content: '',
      username: 'TestUser',
      embeds: [],
      components: [],
    } as unknown as MessageData;
    const result = validateMessage(data);
    expect(typeof result).toBe('string');
    expect((result as string).length).toBeGreaterThan(0);
  });
});

// ============================================================
// Tests: validateDisplayableTextCount (aggregate text limit)
// ============================================================

describe('validateDisplayableTextCount', () => {
  it('returns empty string when total text is within limit', () => {
    const components = [makeTextDisplay('x'.repeat(2000)), makeTextDisplay('x'.repeat(2000))];
    expect(validateDisplayableTextCount(components as SupportedTopLevelComponent[])).toBe('');
  });

  it('returns empty string for exactly 4000 characters', () => {
    const components = [makeTextDisplay('x'.repeat(4000))];
    expect(validateDisplayableTextCount(components as SupportedTopLevelComponent[])).toBe('');
  });

  it('returns error when total text exceeds 4000 characters', () => {
    const components = [makeTextDisplay('x'.repeat(2001)), makeTextDisplay('x'.repeat(2000))];
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).not.toBe('');
    expect(result).toContain('4000');
  });

  it('counts text inside sections', () => {
    const components = [
      { type: 9, components: [makeTextDisplay('x'.repeat(3000))], accessory: makeThumbnail() },
      makeTextDisplay('x'.repeat(1001)),
    ];
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).not.toBe('');
  });

  it('counts text inside containers', () => {
    const components = [
      makeContainer([makeTextDisplay('x'.repeat(3000))]),
      makeTextDisplay('x'.repeat(1001)),
    ];
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).not.toBe('');
  });

  it('counts text inside sections within containers', () => {
    const section = { type: 9, components: [makeTextDisplay('x'.repeat(3000))], accessory: makeThumbnail() };
    const components = [
      makeContainer([section as Record<string, unknown>]),
      makeTextDisplay('x'.repeat(1001)),
    ];
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).not.toBe('');
  });

  it('returns empty string for classic ActionRows (no text displays)', () => {
    const components = [makeActionRow(), makeActionRow()];
    expect(validateDisplayableTextCount(components as SupportedTopLevelComponent[])).toBe('');
  });

  it('returns empty string for empty components array', () => {
    expect(validateDisplayableTextCount([] as SupportedTopLevelComponent[])).toBe('');
  });
});

// ============================================================
// Tests: validateMessage aggregate text integration
// ============================================================

describe('validateMessage aggregate text', () => {
  it('returns error for V2 message with aggregate text > 4000', () => {
    const data = {
      content: '',
      username: 'TestUser',
      embeds: [],
      components: [makeTextDisplay('x'.repeat(2001)), makeTextDisplay('x'.repeat(2000))],
    } as unknown as MessageData;
    const result = validateMessage(data);
    expect(result).not.toBe('');
    expect(result).toContain('4000');
  });

  it('returns empty string for V2 message with aggregate text ≤ 4000', () => {
    const data = {
      content: '',
      username: 'TestUser',
      embeds: [],
      components: [makeTextDisplay('x'.repeat(2000)), makeTextDisplay('x'.repeat(2000))],
    } as unknown as MessageData;
    const result = validateMessage(data);
    expect(result).toBe('');
  });
});

// ============================================================
// QA: aggregate displayable text — additional edge cases
// ============================================================

describe('QA: validateDisplayableTextCount edge cases', () => {
  it('counts many small text displays accurately', () => {
    // 10 × 401 = 4010 > 4000
    const components = Array.from({ length: 10 }, () => makeTextDisplay('x'.repeat(401)));
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).not.toBe('');
  });

  it('accepts many small text displays exactly at limit', () => {
    // 8 × 500 = 4000
    const components = Array.from({ length: 8 }, () => makeTextDisplay('x'.repeat(500)));
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).toBe('');
  });

  it('does not count button labels in ActionRows', () => {
    const components = [
      makeTextDisplay('x'.repeat(4000)),
      makeActionRow([makeLinkButton({ label: 'x'.repeat(80) })]),
    ];
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).toBe('');
  });

  it('handles undefined components in section gracefully', () => {
    const components = [{ type: 9, accessory: makeThumbnail() }];
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).toBe('');
  });

  it('handles undefined components in container gracefully', () => {
    const components = [{ type: 17 }];
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).toBe('');
  });

  it('off-by-one: 4001 total triggers error, 4000 does not', () => {
    const at4000 = [makeTextDisplay('x'.repeat(2000)), makeTextDisplay('x'.repeat(2000))];
    expect(validateDisplayableTextCount(at4000 as SupportedTopLevelComponent[])).toBe('');

    const at4001 = [makeTextDisplay('x'.repeat(2001)), makeTextDisplay('x'.repeat(2000))];
    expect(validateDisplayableTextCount(at4001 as SupportedTopLevelComponent[])).not.toBe('');
  });

  it('error message includes the limit number for user clarity', () => {
    const components = [makeTextDisplay('x'.repeat(4001))];
    const result = validateDisplayableTextCount(components as SupportedTopLevelComponent[]);
    expect(result).toContain('4000');
  });
});

import { describe, expect, it, vi } from 'vitest';

import { applyDisposition, jsonModalSeed, resolveContentLoss } from '~/utils';
import { validateContentRequirements } from '~/utils/limits';

vi.mock('~/env.mjs', () => ({ env: { NEXT_PUBLIC_DISCORD_CLIENT_ID: 'test' } }));

const FLAG = 1 << 15;
const ACTION_ROW = { type: 1, components: [{ type: 2, style: 5, label: 'x', url: 'https://e.co' }] };

const rowDMembers: Array<[string, Record<string, unknown>]> = [
  ['content only (record 5712\'s own shape)', { content: 'hi', flags: FLAG }],
  ['embeds only', { embeds: [{ title: 't' }], flags: FLAG }],
  ['content AND embeds', { content: 'hi', embeds: [{ title: 't' }], flags: FLAG }],
  ['content + a non-V2 action row', { content: 'hi', flags: FLAG, components: [ACTION_ROW] }],
  ['embeds + a non-V2 action row', { embeds: [{ title: 't' }], flags: FLAG, components: [ACTION_ROW] }],
  ['whitespace-padded content', { content: '  hi  ', flags: FLAG }],
  ['flag OR-ed with other bits (SUPPRESS_EMBEDS)', { content: 'hi', flags: FLAG | 4 }],
  ['flag OR-ed with EPHEMERAL', { content: 'hi', flags: FLAG | 64 }],
];

// Every disposition-row-D member must resolve to something the floor accepts, or the fix
// silently drops content instead of loading it.
describe('row D disposition — applyDisposition(rowD) is accepted by the floor', () => {
  it.each(rowDMembers)('row D member — %s — resolves to something the floor accepts', (_label, draft) => {
    const disposition = resolveContentLoss(
      draft.flags as number | undefined,
      draft.components as undefined | { type: number }[],
      draft.content as string | undefined,
      draft.embeds as never,
    );
    expect(disposition.requiresChoice).toBe(false);

    const resolved = applyDisposition(draft as never);
    expect(validateContentRequirements(resolved as never)).toBeUndefined();
  });

  it('and the resolution is genuinely lossless for content (not merely floor-passing)', () => {
    const resolved = applyDisposition({ content: 'hi', flags: FLAG } as never);
    expect((resolved as { content?: string }).content).toBe('hi');
    expect(((resolved as { flags?: number }).flags ?? 0) & FLAG).toBe(0);
  });

  // Pins the property directly (bitwise AND against the flag), not a type assertion that
  // happens to pass on fixtures carrying no other bits — over the two rowDMembers entries that
  // DO carry another bit, so a regression that made applyDisposition drop other bits (not just
  // the V2 bit) would be caught here.
  it('the V2-bit clear preserves other flag bits (SUPPRESS_EMBEDS, EPHEMERAL)', () => {
    const withSuppressEmbeds = applyDisposition({ content: 'hi', flags: FLAG | 4 } as never);
    expect(((withSuppressEmbeds as { flags?: number }).flags ?? 0) & FLAG).toBe(0);
    expect(((withSuppressEmbeds as { flags?: number }).flags ?? 0) & 4).toBe(4);

    const withEphemeral = applyDisposition({ content: 'hi', flags: FLAG | 64 } as never);
    expect(((withEphemeral as { flags?: number }).flags ?? 0) & FLAG).toBe(0);
    expect(((withEphemeral as { flags?: number }).flags ?? 0) & 64).toBe(64);
  });
});

// The fix opens no new hole: what must stay blocked still does.
describe('row D disposition — hole check: the fix opens no new hole', () => {
  const loadDisabled = (draft: Record<string, unknown> | null): boolean => {
    if (!draft) return true;
    return !!validateContentRequirements(applyDisposition(draft as never));
  };

  it('empty draft (no content/comps/flag) stays BLOCKED — floor Branch 2', () => {
    expect(loadDisabled({ flags: 0, content: '', embeds: [], components: [] })).toBe(true);
  });

  it('flag-only empty draft (row C — switchToV2 keeps it empty) stays BLOCKED', () => {
    const d = { flags: FLAG, content: '', embeds: [], components: [] };
    expect(resolveContentLoss(d.flags, d.components as never, d.content, d.embeds).row).toBe('C');
    expect(loadDisabled(d)).toBe(true);
  });

  it('whitespace-only content, no flag/comps stays BLOCKED (trim => empty)', () => {
    expect(loadDisabled({ flags: 0, content: '   ', embeds: [], components: [] })).toBe(true);
  });
});

// Record 5712, end to end, through the shipped seed -> parse -> resolve -> floor pipeline.
describe('row D disposition — record 5712 end to end', () => {
  const STORED_5712_FULL = {
    id: '5712',
    name: 'MOTM',
    data: {
      username: 'MOTM',
      flags: 32768,
      content: 'Complimenti {{user}} ! Sei il Member of The Month in ...',
      embeds: [],
      components: [],
    },
  };
  const seeded = () => JSON.parse(jsonModalSeed(STORED_5712_FULL as never));

  it('the repair now succeeds: resolved draft clears the floor', () => {
    const s = seeded();
    const resolved = applyDisposition(s);
    expect(validateContentRequirements(resolved)).toBeUndefined();
    expect(((resolved as { flags?: number }).flags ?? 0) & FLAG).toBe(0);
    expect((resolved as { content?: string }).content).toBe(s.content);
  });
});

