export function makeMap<T, K extends keyof T>(items: T[], key: K): Map<T[K], T>;
export function makeMap<T, K extends keyof T, U extends keyof T>(items: T[], key: K, valueKey: U): Map<T[K], T[U]>;
export function makeMap<T, K extends keyof T, U extends keyof T>(items: T[], key: K, valueKey?: U): Map<T[K], T[U] | T> {
  const map = new Map<T[K], T | T[U]>();
  for (const item of items) map.set(item[key], valueKey ? item[valueKey] : item);
  return map;
}

type RecordKey = string | number | symbol;
export function makeObject<T, K extends KeysMatching<T, RecordKey>>(items: T[], key: K): Record<RecordKey, T> {
  const obj = {} as Record<RecordKey, T>;
  for (const item of items) obj[item[key] as unknown as RecordKey] = item;
  return obj;
}

import { IS_COMPONENTS_V2_FLAG } from '~/constants/messageLimits';
import { hasV2Components } from '~/utils';

type ModeSwitchDraft = Pick<Partial<MessageData>, 'content' | 'embeds' | 'components' | 'flags'>;

export function isMessageV2(data: Pick<Partial<MessageData>, 'flags' | 'components'>): boolean {
  return hasV2Components(data.components as undefined | { type: number }[])
    || !!((data.flags as number | undefined ?? 0) & IS_COMPONENTS_V2_FLAG);
}

export function detectMessageMode(
  msg: null | undefined | Pick<ActiveMessage, 'data'>,
): MessageMode | null {
  if (!msg) return null;
  return isMessageV2(msg.data) ? 'v2' : 'classic';
}

export function showV2PatchWarning(
  message: null | undefined | Pick<ActiveMessage, 'data'>,
  oldMessage: unknown,
  showEdit: boolean,
): boolean {
  return showEdit && !!oldMessage && !!message && isMessageV2(message.data);
}

export function switchToV2<T extends ModeSwitchDraft>(prev: T): T {
  return {
    ...prev,
    content: '',
    embeds: [],
    flags: ((prev.flags as number | undefined) ?? 0) | IS_COMPONENTS_V2_FLAG,
  };
}

export function switchToClassic<T extends ModeSwitchDraft>(prev: T): T {
  const next: T = {
    ...prev,
    components: (prev.components ?? []).filter(
      (c) => (c as { type: number }).type === 1,
    ),
  };
  next.flags = ((next.flags as number | undefined) ?? 0) & ~IS_COMPONENTS_V2_FLAG;
  return next;
}

export function applyModeSwitch<T extends ModeSwitchDraft>(targetMode: MessageMode, prev: T): T {
  return targetMode === 'v2' ? switchToV2(prev) : switchToClassic(prev);
}

export default <T extends object>(object: T, excluded: string[]) => (Object.keys(object) as string[])
  .reduce<T>((result, key) => {
    if (excluded.indexOf(key) === -1) {
      result[key as keyof T] = object[key as keyof T];
    }

    return result;
  // eslint-disable-next-line @typescript-eslint/prefer-reduce-type-parameter
  }, {} as T);

